"""Biology practicals: microscope counts (stomata, mitosis, pollen), physiology
(photosynthesis, enzymes, microbial growth), genetics and DNA (classes 10–12,
UG and PG)."""


def add(lab, W, Q):
    MICRO = W('Compound microscope', 'संयुक्त सूक्ष्मदर्शी', 'ಸಂಯುಕ್ತ ಸೂಕ್ಷ್ಮದರ್ಶಕ')
    SLIDES = W('Slides, cover slips, forceps and a brush', 'स्लाइड, कवर स्लिप, चिमटी और ब्रश', 'ಸ್ಲೈಡ್‌ಗಳು, ಕವರ್ ಸ್ಲಿಪ್‌ಗಳು, ಚಿಮುಟ ಮತ್ತು ಬ್ರಷ್')
    FOCUS = W('Focus first with the low-power objective, then turn to high power and use only the fine adjustment.', 'पहले निम्न-क्षमता अभिदृश्यक से फ़ोकस करें, फिर उच्च क्षमता पर जाकर केवल सूक्ष्म समायोजक चलाएँ।', 'ಮೊದಲು ಕಡಿಮೆ ಸಾಮರ್ಥ್ಯದ ವಸ್ತುಮಸೂರದಲ್ಲಿ ಕೇಂದ್ರೀಕರಿಸಿ, ನಂತರ ಹೆಚ್ಚಿನ ಸಾಮರ್ಥ್ಯಕ್ಕೆ ತಿರುಗಿಸಿ ಸೂಕ್ಷ್ಮ ಹೊಂದಾಣಿಕೆಯನ್ನು ಮಾತ್ರ ಬಳಸಿ.')
    NOBUBBLE = W('Lower the cover slip slowly from one side so that no air bubbles are trapped.', 'कवर स्लिप को एक ओर से धीरे-धीरे रखें ताकि वायु बुलबुले न फँसें।', 'ಗಾಳಿ ಗುಳ್ಳೆಗಳು ಸಿಕ್ಕಿಕೊಳ್ಳದಂತೆ ಕವರ್ ಸ್ಲಿಪ್ ಅನ್ನು ಒಂದು ಬದಿಯಿಂದ ನಿಧಾನವಾಗಿ ಇಳಿಸಿ.')
    FIELDS = W('Count in several fields chosen without looking for "good" ones, and take the mean.', 'कई क्षेत्रों में गिनें, "अच्छे" क्षेत्र छाँटे बिना, और माध्य लें।', '"ಒಳ್ಳೆಯ" ಕ್ಷೇತ್ರಗಳನ್ನು ಹುಡುಕದೆ ಹಲವು ಕ್ಷೇತ್ರಗಳಲ್ಲಿ ಎಣಿಸಿ ಸರಾಸರಿ ತೆಗೆದುಕೊಳ್ಳಿ.')
    STERILE = W('Work near a flame with sterile glassware; never smell or mouth-pipette cultures.', 'ज्वाला के पास निर्जीवाणुकृत काँच के बर्तनों से काम करें; संवर्धन को कभी सूँघें नहीं या मुँह से पिपेट न करें।', 'ಜ್ವಾಲೆಯ ಬಳಿ ನಿರ್ಜೀವೀಕೃತ ಗಾಜಿನ ಸಾಮಗ್ರಿಗಳೊಂದಿಗೆ ಕೆಲಸ ಮಾಡಿ; ಸಂವರ್ಧನೆಯನ್ನು ಎಂದೂ ಮೂಸಬೇಡಿ ಅಥವಾ ಬಾಯಿಂದ ಪಿಪೆಟ್ ಮಾಡಬೇಡಿ.')
    GLOVES = W('Wear gloves and a lab coat; dispose of biological waste in the marked bin.', 'दस्ताने और प्रयोगशाला कोट पहनें; जैविक कचरा चिह्नित डिब्बे में डालें।', 'ಕೈಗವಸು ಮತ್ತು ಪ್ರಯೋಗಾಲಯದ ಕೋಟು ಧರಿಸಿ; ಜೈವಿಕ ತ್ಯಾಜ್ಯವನ್ನು ಗುರುತಿಸಿದ ತೊಟ್ಟಿಗೆ ಹಾಕಿ.')
    bio = dict(subject='Biology', domain='biology')

    lab(id='stomatal-index', bench='stomata', levels=[10, 11], curricula=['cbse', 'ncert', 'ka-puc'], **bio,
        keywords=['stomata', 'stomatal index', 'leaf peel', 'epidermis', 'transpiration', 'guard cells', 'microscope'],
        title=W('Stomatal index of a leaf', 'पत्ती का रंध्र सूचकांक', 'ಎಲೆಯ ಪತ್ರರಂಧ್ರ ಸೂಚ್ಯಂಕ'),
        summary=W('Count stomata and epidermal cells in leaf peels and compare the two surfaces of a leaf.', 'पत्ती की झिल्लियों में रंध्र और बाह्यत्वचा कोशिकाएँ गिनें और पत्ती की दोनों सतहों की तुलना करें।', 'ಎಲೆಯ ಸಿಪ್ಪೆಗಳಲ್ಲಿ ಪತ್ರರಂಧ್ರಗಳು ಮತ್ತು ಹೊರಚರ್ಮ ಕೋಶಗಳನ್ನು ಎಣಿಸಿ, ಎಲೆಯ ಎರಡು ಮೇಲ್ಮೈಗಳನ್ನು ಹೋಲಿಸಿ.'),
        aim=W('To find the stomatal index of the upper and lower surfaces of a leaf.', 'पत्ती की ऊपरी और निचली सतहों का रंध्र सूचकांक ज्ञात करना।', 'ಎಲೆಯ ಮೇಲಿನ ಮತ್ತು ಕೆಳಗಿನ ಮೇಲ್ಮೈಗಳ ಪತ್ರರಂಧ್ರ ಸೂಚ್ಯಂಕ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('Stomata are pores, each between two guard cells, through which the leaf exchanges gases and loses water. The stomatal index SI = S ÷ (S + E) × 100, where S is the number of stomata and E the number of other epidermal cells in the same area. Unlike the number per mm², it hardly changes with leaf size, so it is a fixed feature of the species and surface.', 'रंध्र छिद्र हैं, प्रत्येक दो द्वार कोशिकाओं के बीच, जिनसे पत्ती गैसों का आदान-प्रदान करती है और जल खोती है। रंध्र सूचकांक SI = S ÷ (S + E) × 100, जहाँ S रंध्रों की संख्या और E उसी क्षेत्र में अन्य बाह्यत्वचा कोशिकाओं की संख्या है। प्रति mm² संख्या के विपरीत यह पत्ती के आकार से लगभग नहीं बदलता, इसलिए यह जाति और सतह का स्थिर लक्षण है।', 'ಪತ್ರರಂಧ್ರಗಳು ಎರಡು ಕಾವಲು ಕೋಶಗಳ ನಡುವಿನ ರಂಧ್ರಗಳು; ಇವುಗಳ ಮೂಲಕ ಎಲೆ ಅನಿಲ ವಿನಿಮಯ ಮಾಡುತ್ತದೆ ಮತ್ತು ನೀರು ಕಳೆದುಕೊಳ್ಳುತ್ತದೆ. ಪತ್ರರಂಧ್ರ ಸೂಚ್ಯಂಕ SI = S ÷ (S + E) × 100; S ಪತ್ರರಂಧ್ರಗಳ ಸಂಖ್ಯೆ, E ಅದೇ ಪ್ರದೇಶದ ಇತರ ಹೊರಚರ್ಮ ಕೋಶಗಳ ಸಂಖ್ಯೆ. ಪ್ರತಿ mm² ಸಂಖ್ಯೆಯಂತಲ್ಲದೆ ಇದು ಎಲೆಯ ಗಾತ್ರದೊಂದಿಗೆ ಬಹುತೇಕ ಬದಲಾಗುವುದಿಲ್ಲ; ಆದ್ದರಿಂದ ಇದು ಪ್ರಭೇದ ಮತ್ತು ಮೇಲ್ಮೈಯ ಸ್ಥಿರ ಲಕ್ಷಣ.'),
        apparatus=[MICRO, SLIDES, W('Fresh leaves, safranin stain and glycerine', 'ताज़ी पत्तियाँ, सैफ़्रानिन अभिरंजक और ग्लिसरीन', 'ತಾಜಾ ಎಲೆಗಳು, ಸಫ್ರಾನಿನ್ ಬಣ್ಣಕಾರಕ ಮತ್ತು ಗ್ಲಿಸರಿನ್')],
        steps=[W('Peel a thin strip of epidermis from the lower surface of the leaf and stain it with safranin.', 'पत्ती की निचली सतह से बाह्यत्वचा की पतली पट्टी उतारें और सैफ़्रानिन से रँगें।', 'ಎಲೆಯ ಕೆಳಗಿನ ಮೇಲ್ಮೈಯಿಂದ ಹೊರಚರ್ಮದ ತೆಳು ಪಟ್ಟಿ ಸುಲಿದು ಸಫ್ರಾನಿನ್‌ನಿಂದ ಬಣ್ಣ ಹಚ್ಚಿ.'),
               W('Mount it in glycerine under a cover slip and find the guard cells under high power.', 'इसे ग्लिसरीन में कवर स्लिप के नीचे रखें और उच्च क्षमता पर द्वार कोशिकाएँ ढूँढें।', 'ಅದನ್ನು ಗ್ಲಿಸರಿನ್‌ನಲ್ಲಿ ಕವರ್ ಸ್ಲಿಪ್ ಅಡಿ ಇಟ್ಟು ಹೆಚ್ಚಿನ ಸಾಮರ್ಥ್ಯದಲ್ಲಿ ಕಾವಲು ಕೋಶಗಳನ್ನು ಹುಡುಕಿ.'),
               W('In each field count the stomata (S) and the other epidermal cells (E); record the field.', 'हर क्षेत्र में रंध्र (S) और अन्य बाह्यत्वचा कोशिकाएँ (E) गिनें; क्षेत्र दर्ज करें।', 'ಪ್ರತಿ ಕ್ಷೇತ್ರದಲ್ಲಿ ಪತ್ರರಂಧ್ರಗಳು (S) ಮತ್ತು ಇತರ ಹೊರಚರ್ಮ ಕೋಶಗಳನ್ನು (E) ಎಣಿಸಿ; ಕ್ಷೇತ್ರ ದಾಖಲಿಸಿ.'),
               W('Repeat for at least five fields, then do the same for the upper surface and a grass leaf.', 'कम से कम पाँच क्षेत्रों के लिए दोहराएँ, फिर ऊपरी सतह और घास की पत्ती के लिए भी।', 'ಕನಿಷ್ಠ ಐದು ಕ್ಷೇತ್ರಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ, ನಂತರ ಮೇಲಿನ ಮೇಲ್ಮೈ ಮತ್ತು ಹುಲ್ಲಿನ ಎಲೆಗೂ ಮಾಡಿ.'),
               W('Find the mean stomatal index of each surface with its standard error.', 'हर सतह का माध्य रंध्र सूचकांक उसकी मानक त्रुटि सहित ज्ञात करें।', 'ಪ್ರತಿ ಮೇಲ್ಮೈಯ ಸರಾಸರಿ ಪತ್ರರಂಧ್ರ ಸೂಚ್ಯಂಕವನ್ನು ಅದರ ಪ್ರಮಾಣಿತ ದೋಷದೊಂದಿಗೆ ಕಂಡುಹಿಡಿಯಿರಿ.')],
        precautions=[NOBUBBLE, FIELDS, W('Count a cell cut by the edge of the field only on two sides (say top and left).', 'क्षेत्र के किनारे से कटी कोशिका को केवल दो ओर (जैसे ऊपर और बाएँ) गिनें।', 'ಕ್ಷೇತ್ರದ ಅಂಚಿನಿಂದ ಕತ್ತರಿಸಿದ ಕೋಶವನ್ನು ಎರಡು ಬದಿಗಳಲ್ಲಿ ಮಾತ್ರ (ಮೇಲೆ ಮತ್ತು ಎಡ) ಎಣಿಸಿ.')],
        conclusion=W('The lower surface of a dicot leaf has a higher stomatal index than the upper; a grass leaf has stomata on both surfaces.', 'द्विबीजपत्री पत्ती की निचली सतह का रंध्र सूचकांक ऊपरी से अधिक है; घास की पत्ती की दोनों सतहों पर रंध्र होते हैं।', 'ದ್ವಿದಳ ಎಲೆಯ ಕೆಳಗಿನ ಮೇಲ್ಮೈಯ ಪತ್ರರಂಧ್ರ ಸೂಚ್ಯಂಕ ಮೇಲಿನದಕ್ಕಿಂತ ಹೆಚ್ಚು; ಹುಲ್ಲಿನ ಎಲೆಯ ಎರಡೂ ಮೇಲ್ಮೈಗಳಲ್ಲಿ ಪತ್ರರಂಧ್ರಗಳಿವೆ.'),
        viva=[Q(W('What controls the opening of a stoma?', 'रंध्र के खुलने को क्या नियंत्रित करता है?', 'ಪತ್ರರಂಧ್ರ ತೆರೆಯುವುದನ್ನು ಯಾವುದು ನಿಯಂತ್ರಿಸುತ್ತದೆ?'), W('The guard cells: they swell with water and bow apart to open the pore.', 'द्वार कोशिकाएँ: वे जल से फूलकर मुड़ती हैं और छिद्र खोलती हैं।', 'ಕಾವಲು ಕೋಶಗಳು: ಅವು ನೀರಿನಿಂದ ಉಬ್ಬಿ ಬಾಗಿ ರಂಧ್ರವನ್ನು ತೆರೆಯುತ್ತವೆ.')),
              Q(W('Why are there fewer stomata on the upper surface?', 'ऊपरी सतह पर कम रंध्र क्यों होते हैं?', 'ಮೇಲಿನ ಮೇಲ್ಮೈಯಲ್ಲಿ ಪತ್ರರಂಧ್ರಗಳು ಏಕೆ ಕಡಿಮೆ?'), W('It faces the sun; fewer pores there reduce water loss.', 'यह धूप की ओर है; वहाँ कम छिद्र होने से जल हानि घटती है।', 'ಅದು ಸೂರ್ಯನ ಕಡೆ ಮುಖಮಾಡಿದೆ; ಅಲ್ಲಿ ಕಡಿಮೆ ರಂಧ್ರಗಳಿದ್ದರೆ ನೀರಿನ ನಷ್ಟ ಕಡಿಮೆ.')),
              Q(W('Why use the index rather than stomata per mm²?', 'प्रति mm² रंध्रों के बजाय सूचकांक क्यों?', 'ಪ್ರತಿ mm² ಪತ್ರರಂಧ್ರಗಳ ಬದಲು ಸೂಚ್ಯಂಕ ಏಕೆ?'), W('Cells grow larger in big leaves, changing the count per mm², but the share of stomata stays nearly the same.', 'बड़ी पत्तियों में कोशिकाएँ बड़ी होती हैं, जिससे प्रति mm² गिनती बदलती है, पर रंध्रों का अनुपात लगभग वही रहता है।', 'ದೊಡ್ಡ ಎಲೆಗಳಲ್ಲಿ ಕೋಶಗಳು ದೊಡ್ಡವಾಗಿ ಪ್ರತಿ mm² ಎಣಿಕೆ ಬದಲಾಗುತ್ತದೆ, ಆದರೆ ಪತ್ರರಂಧ್ರಗಳ ಪಾಲು ಬಹುತೇಕ ಅದೇ ಇರುತ್ತದೆ.'))])

    lab(id='mitosis-onion-root', bench='mitosis', levels=[11, 12], curricula=['cbse', 'ncert', 'ka-puc'], **bio,
        keywords=['mitosis', 'cell division', 'onion root tip', 'mitotic index', 'prophase', 'metaphase', 'anaphase', 'telophase', 'cell cycle'],
        title=W('Mitosis in onion root tip cells', 'प्याज़ की जड़ के सिरे की कोशिकाओं में समसूत्री विभाजन', 'ಈರುಳ್ಳಿ ಬೇರಿನ ತುದಿಯ ಕೋಶಗಳಲ್ಲಿ ಸಮವಿಭಜನೆ'),
        summary=W('Identify the stages of mitosis in a stained root-tip squash, find the mitotic index and how long each stage lasts.', 'अभिरंजित जड़-सिरे के स्क्वैश में समसूत्री विभाजन की अवस्थाएँ पहचानें, समसूत्री सूचकांक और हर अवस्था की अवधि ज्ञात करें।', 'ಬಣ್ಣ ಹಚ್ಚಿದ ಬೇರಿನ ತುದಿಯ ಸ್ಕ್ವಾಷ್‌ನಲ್ಲಿ ಸಮವಿಭಜನೆಯ ಹಂತಗಳನ್ನು ಗುರುತಿಸಿ, ಸಮವಿಭಜನಾ ಸೂಚ್ಯಂಕ ಮತ್ತು ಪ್ರತಿ ಹಂತದ ಅವಧಿ ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To study the stages of mitosis in onion root tip cells and find the mitotic index.', 'प्याज़ की जड़ के सिरे की कोशिकाओं में समसूत्री विभाजन की अवस्थाओं का अध्ययन करना और समसूत्री सूचकांक ज्ञात करना।', 'ಈರುಳ್ಳಿ ಬೇರಿನ ತುದಿಯ ಕೋಶಗಳಲ್ಲಿ ಸಮವಿಭಜನೆಯ ಹಂತಗಳನ್ನು ಅಧ್ಯಯನ ಮಾಡಿ ಸಮವಿಭಜನಾ ಸೂಚ್ಯಂಕ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('Cells divide only in the meristem just behind the root cap. Most cells are in interphase; the rest are in prophase, metaphase, anaphase or telophase. Mitotic index = dividing cells ÷ all cells × 100. Since cells are caught at random, the share of cells in a stage is the share of the cycle it lasts.', 'कोशिकाएँ केवल मूल गोप के ठीक पीछे विभज्योतक में विभाजित होती हैं। अधिकतर कोशिकाएँ अंतरावस्था में होती हैं; शेष पूर्वावस्था, मध्यावस्था, पश्चावस्था या अंत्यावस्था में। समसूत्री सूचकांक = विभाजित होती कोशिकाएँ ÷ सभी कोशिकाएँ × 100। चूँकि कोशिकाएँ यादृच्छिक रूप से पकड़ी जाती हैं, किसी अवस्था में कोशिकाओं का अंश चक्र में उसकी अवधि का अंश है।', 'ಬೇರಿನ ಟೊಪ್ಪಿಯ ಹಿಂದಿರುವ ವಿಭಜಕ ಅಂಗಾಂಶದಲ್ಲಿ ಮಾತ್ರ ಕೋಶಗಳು ವಿಭಜನೆಯಾಗುತ್ತವೆ. ಹೆಚ್ಚಿನ ಕೋಶಗಳು ಅಂತರಹಂತದಲ್ಲಿರುತ್ತವೆ; ಉಳಿದವು ಪೂರ್ವಹಂತ, ಮಧ್ಯಹಂತ, ಪಶ್ಚಹಂತ ಅಥವಾ ಅಂತ್ಯಹಂತದಲ್ಲಿ. ಸಮವಿಭಜನಾ ಸೂಚ್ಯಂಕ = ವಿಭಜನೆಯಾಗುತ್ತಿರುವ ಕೋಶಗಳು ÷ ಎಲ್ಲ ಕೋಶಗಳು × 100. ಕೋಶಗಳು ಯಾದೃಚ್ಛಿಕವಾಗಿ ಸಿಗುವುದರಿಂದ, ಒಂದು ಹಂತದಲ್ಲಿರುವ ಕೋಶಗಳ ಪಾಲು ಚಕ್ರದಲ್ಲಿ ಅದರ ಅವಧಿಯ ಪಾಲು.'),
        apparatus=[MICRO, SLIDES, W('Onion root tips, 1 M HCl, acetocarmine stain and a spirit lamp', 'प्याज़ की जड़ के सिरे, 1 M HCl, ऐसीटोकार्मिन अभिरंजक और स्पिरिट लैम्प', 'ಈರುಳ್ಳಿ ಬೇರಿನ ತುದಿಗಳು, 1 M HCl, ಅಸಿಟೋಕಾರ್ಮಿನ್ ಬಣ್ಣಕಾರಕ ಮತ್ತು ಸ್ಪಿರಿಟ್ ದೀಪ')],
        steps=[W('Grow onion roots in water for 3–4 days and cut the tips (2 cm) in the morning.', 'प्याज़ की जड़ें 3–4 दिन जल में उगाएँ और सुबह सिरे (2 cm) काटें।', 'ಈರುಳ್ಳಿ ಬೇರುಗಳನ್ನು 3–4 ದಿನ ನೀರಿನಲ್ಲಿ ಬೆಳೆಸಿ ಬೆಳಿಗ್ಗೆ ತುದಿಗಳನ್ನು (2 cm) ಕತ್ತರಿಸಿ.'),
               W('Warm the tips in 1 M HCl with acetocarmine for a few minutes to soften and stain them.', 'सिरों को नरम और अभिरंजित करने के लिए ऐसीटोकार्मिन के साथ 1 M HCl में कुछ मिनट गुनगुना करें।', 'ತುದಿಗಳನ್ನು ಮೃದುಗೊಳಿಸಿ ಬಣ್ಣ ಹಚ್ಚಲು ಅಸಿಟೋಕಾರ್ಮಿನ್ ಸಹಿತ 1 M HCl ನಲ್ಲಿ ಕೆಲವು ನಿಮಿಷ ಬೆಚ್ಚಗೆ ಮಾಡಿ.'),
               W('Cut off the last 2 mm, put it on a slide with a drop of stain, cover and squash gently with the thumb.', 'अंतिम 2 mm काटकर अभिरंजक की बूँद के साथ स्लाइड पर रखें, ढकें और अँगूठे से धीरे से दबाएँ।', 'ಕೊನೆಯ 2 mm ಕತ್ತರಿಸಿ ಬಣ್ಣಕಾರಕದ ಹನಿಯೊಂದಿಗೆ ಸ್ಲೈಡ್ ಮೇಲೆ ಇಟ್ಟು, ಮುಚ್ಚಿ ಹೆಬ್ಬೆರಳಿನಿಂದ ನಿಧಾನವಾಗಿ ಒತ್ತಿ.'),
               W('In each field count the cells in interphase and in each stage of division.', 'हर क्षेत्र में अंतरावस्था और विभाजन की हर अवस्था की कोशिकाएँ गिनें।', 'ಪ್ರತಿ ಕ್ಷೇತ್ರದಲ್ಲಿ ಅಂತರಹಂತ ಮತ್ತು ವಿಭಜನೆಯ ಪ್ರತಿ ಹಂತದ ಕೋಶಗಳನ್ನು ಎಣಿಸಿ.'),
               W('Do the same in the zone of elongation and compare the mitotic indices.', 'दीर्घीकरण क्षेत्र में भी ऐसा ही करें और समसूत्री सूचकांकों की तुलना करें।', 'ಉದ್ದವಾಗುವ ವಲಯದಲ್ಲೂ ಹೀಗೆ ಮಾಡಿ ಸಮವಿಭಜನಾ ಸೂಚ್ಯಂಕಗಳನ್ನು ಹೋಲಿಸಿ.')],
        precautions=[W('Do not boil the root tips; overheating destroys the chromosomes.', 'जड़ के सिरों को उबालें नहीं; अधिक ताप गुणसूत्रों को नष्ट कर देता है।', 'ಬೇರಿನ ತುದಿಗಳನ್ನು ಕುದಿಸಬೇಡಿ; ಅತಿ ಶಾಖ ವರ್ಣತಂತುಗಳನ್ನು ನಾಶ ಮಾಡುತ್ತದೆ.'), W('Squash vertically without sliding the cover slip.', 'कवर स्लिप को खिसकाए बिना सीधा दबाएँ।', 'ಕವರ್ ಸ್ಲಿಪ್ ಜಾರಿಸದೆ ನೇರವಾಗಿ ಒತ್ತಿ.'), FIELDS],
        conclusion=W('The root tip meristem has a high mitotic index; prophase is the longest stage of division and anaphase the shortest.', 'जड़ के सिरे के विभज्योतक का समसूत्री सूचकांक अधिक है; विभाजन में पूर्वावस्था सबसे लंबी और पश्चावस्था सबसे छोटी अवस्था है।', 'ಬೇರಿನ ತುದಿಯ ವಿಭಜಕ ಅಂಗಾಂಶದ ಸಮವಿಭಜನಾ ಸೂಚ್ಯಂಕ ಹೆಚ್ಚು; ವಿಭಜನೆಯಲ್ಲಿ ಪೂರ್ವಹಂತ ಅತಿ ದೀರ್ಘ, ಪಶ್ಚಹಂತ ಅತಿ ಚಿಕ್ಕ.'),
        viva=[Q(W('In which stage are chromosomes clearest?', 'किस अवस्था में गुणसूत्र सबसे स्पष्ट दिखते हैं?', 'ಯಾವ ಹಂತದಲ್ಲಿ ವರ್ಣತಂತುಗಳು ಅತಿ ಸ್ಪಷ್ಟ?'), W('Metaphase, lined up at the equator of the spindle.', 'मध्यावस्था, जब वे तर्कु की मध्य रेखा पर पंक्तिबद्ध होते हैं।', 'ಮಧ್ಯಹಂತ; ಅವು ತರ್ಕುವಿನ ಸಮಭಾಜಕದಲ್ಲಿ ಸಾಲಾಗಿರುತ್ತವೆ.')),
              Q(W('Why are root tips cut in the morning?', 'जड़ के सिरे सुबह क्यों काटे जाते हैं?', 'ಬೇರಿನ ತುದಿಗಳನ್ನು ಬೆಳಿಗ್ಗೆ ಏಕೆ ಕತ್ತರಿಸುತ್ತಾರೆ?'), W('Most cells in onion roots divide in the morning hours.', 'प्याज़ की जड़ों में अधिकतर कोशिकाएँ सुबह विभाजित होती हैं।', 'ಈರುಳ್ಳಿ ಬೇರುಗಳಲ್ಲಿ ಹೆಚ್ಚಿನ ಕೋಶಗಳು ಬೆಳಿಗ್ಗೆ ವಿಭಜನೆಯಾಗುತ್ತವೆ.')),
              Q(W('What does HCl do?', 'HCl क्या करता है?', 'HCl ಏನು ಮಾಡುತ್ತದೆ?'), W('It dissolves the material holding cells together, so they spread out when squashed.', 'यह कोशिकाओं को जोड़ने वाले पदार्थ को घोल देता है, ताकि दबाने पर वे फैल जाएँ।', 'ಕೋಶಗಳನ್ನು ಹಿಡಿದಿಡುವ ವಸ್ತುವನ್ನು ಕರಗಿಸುತ್ತದೆ; ಹೀಗಾಗಿ ಒತ್ತಿದಾಗ ಅವು ಹರಡುತ್ತವೆ.'))])

    lab(id='pollen-germination', bench='pollen', levels=[12], curricula=['cbse', 'ncert', 'ka-puc'], **bio,
        keywords=['pollen', 'pollen germination', 'pollen tube', 'sucrose', 'sexual reproduction in flowering plants', 'osmosis'],
        title=W('Pollen germination on sucrose', 'सुक्रोज़ पर परागकण अंकुरण', 'ಸುಕ್ರೋಸ್ ಮೇಲೆ ಪರಾಗ ಕಣ ಮೊಳಕೆ'),
        summary=W('Sow pollen in sucrose solutions of different strengths and follow how many grains grow a tube.', 'विभिन्न सांद्रता के सुक्रोज़ विलयनों में परागकण बोएँ और देखें कितने कणों में नलिका बनती है।', 'ಬೇರೆ ಬೇರೆ ಸಾಂದ್ರತೆಯ ಸುಕ್ರೋಸ್ ದ್ರಾವಣಗಳಲ್ಲಿ ಪರಾಗ ಕಣಗಳನ್ನು ಬಿತ್ತಿ ಎಷ್ಟು ಕಣಗಳು ನಳಿಕೆ ಬೆಳೆಸುತ್ತವೆ ಎಂದು ನೋಡಿ.'),
        aim=W('To study pollen germination on a slide and find the best sucrose concentration for it.', 'स्लाइड पर परागकण अंकुरण का अध्ययन करना और उसके लिए सर्वोत्तम सुक्रोज़ सांद्रता ज्ञात करना।', 'ಸ್ಲೈಡ್ ಮೇಲೆ ಪರಾಗ ಕಣ ಮೊಳಕೆಯನ್ನು ಅಧ್ಯಯನ ಮಾಡಿ ಅದಕ್ಕೆ ಅತ್ಯುತ್ತಮ ಸುಕ್ರೋಸ್ ಸಾಂದ್ರತೆ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('On the stigma a pollen grain absorbs water and sugar and grows a pollen tube that carries the male gametes to the ovule. Sucrose solution imitates the stigma: too dilute and the grain has no food (and may burst); too strong and water is drawn out of it.', 'वर्तिकाग्र पर परागकण जल और शर्करा सोखकर परागनलिका बनाता है जो नर युग्मकों को बीजांड तक ले जाती है। सुक्रोज़ विलयन वर्तिकाग्र की नकल करता है: बहुत तनु हो तो कण को भोजन नहीं मिलता (और वह फट सकता है); बहुत सांद्र हो तो उससे जल बाहर खिंच जाता है।', 'ಶಲಾಕಾಗ್ರದ ಮೇಲೆ ಪರಾಗ ಕಣ ನೀರು ಮತ್ತು ಸಕ್ಕರೆ ಹೀರಿ ಪರಾಗ ನಳಿಕೆ ಬೆಳೆಸುತ್ತದೆ; ಅದು ಪುರುಷ ಯುಗ್ಮಕಗಳನ್ನು ಅಂಡಕಕ್ಕೆ ಒಯ್ಯುತ್ತದೆ. ಸುಕ್ರೋಸ್ ದ್ರಾವಣ ಶಲಾಕಾಗ್ರವನ್ನು ಅನುಕರಿಸುತ್ತದೆ: ತುಂಬ ವಿರಳವಾದರೆ ಕಣಕ್ಕೆ ಆಹಾರ ಇಲ್ಲ (ಒಡೆಯಲೂಬಹುದು); ತುಂಬ ಸಾರವಾದರೆ ಅದರಿಂದ ನೀರು ಹೊರಸೆಳೆಯಲ್ಪಡುತ್ತದೆ.'),
        apparatus=[MICRO, W('Cavity slides and sucrose solutions (0–30 %)', 'गर्त स्लाइड और सुक्रोज़ विलयन (0–30 %)', 'ಕುಳಿ ಸ್ಲೈಡ್‌ಗಳು ಮತ್ತು ಸುಕ್ರೋಸ್ ದ್ರಾವಣಗಳು (0–30 %)'), W('Freshly opened flowers (pea, Tradescantia or Hibiscus)', 'ताज़े खिले फूल (मटर, ट्रेडस्कैंशिया या गुड़हल)', 'ಹೊಸದಾಗಿ ಅರಳಿದ ಹೂಗಳು (ಬಟಾಣಿ, ಟ್ರೇಡ್‌ಸ್ಕ್ಯಾಂಶಿಯಾ ಅಥವಾ ದಾಸವಾಳ)')],
        steps=[W('Put a drop of each sucrose solution in a separate cavity slide.', 'हर सुक्रोज़ विलयन की एक बूँद अलग गर्त स्लाइड में डालें।', 'ಪ್ರತಿ ಸುಕ್ರೋಸ್ ದ್ರಾವಣದ ಒಂದು ಹನಿಯನ್ನು ಬೇರೆ ಬೇರೆ ಕುಳಿ ಸ್ಲೈಡ್‌ಗೆ ಹಾಕಿ.'),
               W('Dust pollen from a fresh anther onto each drop and cover.', 'ताज़े परागकोश से हर बूँद पर परागकण झाड़ें और ढकें।', 'ತಾಜಾ ಪರಾಗಕೋಶದಿಂದ ಪ್ರತಿ ಹನಿಯ ಮೇಲೆ ಪರಾಗ ಉದುರಿಸಿ ಮುಚ್ಚಿ.'),
               W('Every 15–30 minutes count the grains with a tube longer than the grain, and all the grains, in one field.', 'हर 15–30 मिनट पर एक क्षेत्र में कण से लंबी नलिका वाले कण और सभी कण गिनें।', 'ಪ್ರತಿ 15–30 ನಿಮಿಷಕ್ಕೊಮ್ಮೆ ಒಂದು ಕ್ಷೇತ್ರದಲ್ಲಿ ಕಣಕ್ಕಿಂತ ಉದ್ದ ನಳಿಕೆಯಿರುವ ಕಣಗಳನ್ನು ಮತ್ತು ಎಲ್ಲ ಕಣಗಳನ್ನು ಎಣಿಸಿ.'),
               W('Work out the percentage germinated and plot it against time for each concentration.', 'अंकुरित प्रतिशत निकालें और हर सांद्रता के लिए समय के विरुद्ध आलेखित करें।', 'ಮೊಳಕೆಯೊಡೆದ ಶೇಕಡಾ ಲೆಕ್ಕಿಸಿ ಪ್ರತಿ ಸಾಂದ್ರತೆಗೆ ಸಮಯದ ವಿರುದ್ಧ ನಕ್ಷೆ ಮಾಡಿ.')],
        precautions=[W('Use pollen from flowers that have just opened.', 'अभी-अभी खिले फूलों के परागकण लें।', 'ಈಗಷ್ಟೇ ಅರಳಿದ ಹೂಗಳ ಪರಾಗ ಬಳಸಿ.'), W('Keep the slides in a moist chamber so the drops do not dry.', 'स्लाइडों को नम कक्ष में रखें ताकि बूँदें न सूखें।', 'ಹನಿಗಳು ಒಣಗದಂತೆ ಸ್ಲೈಡ್‌ಗಳನ್ನು ತೇವದ ಕೋಣೆಯಲ್ಲಿ ಇಡಿ.')],
        conclusion=W('Pollen germinates best in a moderate sucrose solution (about 10–15 %); very dilute or very strong solutions give few tubes.', 'परागकण मध्यम सुक्रोज़ विलयन (लगभग 10–15 %) में सबसे अच्छा अंकुरित होता है; बहुत तनु या बहुत सांद्र विलयन में कम नलिकाएँ बनती हैं।', 'ಮಧ್ಯಮ ಸುಕ್ರೋಸ್ ದ್ರಾವಣದಲ್ಲಿ (ಸುಮಾರು 10–15 %) ಪರಾಗ ಅತ್ಯುತ್ತಮವಾಗಿ ಮೊಳಕೆಯೊಡೆಯುತ್ತದೆ; ತುಂಬ ವಿರಳ ಅಥವಾ ತುಂಬ ಸಾರ ದ್ರಾವಣಗಳಲ್ಲಿ ಕೆಲವೇ ನಳಿಕೆಗಳು.'),
        viva=[Q(W('What does the pollen tube carry?', 'परागनलिका क्या ले जाती है?', 'ಪರಾಗ ನಳಿಕೆ ಏನನ್ನು ಒಯ್ಯುತ್ತದೆ?'), W('Two male gametes, to the egg and the polar nuclei (double fertilisation).', 'दो नर युग्मक, अंड और ध्रुवीय केंद्रकों तक (द्विनिषेचन)।', 'ಎರಡು ಪುರುಷ ಯುಗ್ಮಕಗಳು, ಅಂಡ ಮತ್ತು ಧ್ರುವೀಯ ಕೋಶಕೇಂದ್ರಗಳಿಗೆ (ದ್ವಿಗರ್ಭಧಾರಣೆ).')),
              Q(W('Through which pore does the tube come out?', 'नलिका किस छिद्र से निकलती है?', 'ನಳಿಕೆ ಯಾವ ರಂಧ್ರದಿಂದ ಹೊರಬರುತ್ತದೆ?'), W('A germ pore in the outer wall (exine).', 'बाहरी भित्ति (बाह्यचोल) के जनन छिद्र से।', 'ಹೊರಗೋಡೆಯ (ಎಕ್ಸೈನ್) ಮೊಳಕೆ ರಂಧ್ರದಿಂದ.')),
              Q(W('Why does 30 % sucrose give few tubes?', '30 % सुक्रोज़ में कम नलिकाएँ क्यों बनती हैं?', '30 % ಸುಕ್ರೋಸ್‌ನಲ್ಲಿ ಏಕೆ ಕೆಲವೇ ನಳಿಕೆಗಳು?'), W('The solution is hypertonic: it draws water out of the grains by osmosis.', 'विलयन अतिपरासारी है: वह परासरण से कणों से जल खींच लेता है।', 'ದ್ರಾವಣ ಅತಿಸಾರಕ: ಅದು ಆಸ್ಮಾಸಿಸ್‌ನಿಂದ ಕಣಗಳಿಂದ ನೀರು ಸೆಳೆಯುತ್ತದೆ.'))])

    lab(id='photosynthesis-light', bench='photosynthesis', levels=[10, 11], curricula=['cbse', 'ncert', 'ka-sslc', 'ka-puc'], **bio,
        keywords=['photosynthesis', 'light intensity', 'limiting factor', 'hydrilla', 'oxygen', 'inverse square law', 'carbon dioxide'],
        title=W('Rate of photosynthesis and light', 'प्रकाश संश्लेषण की दर और प्रकाश', 'ದ್ಯುತಿಸಂಶ್ಲೇಷಣೆಯ ದರ ಮತ್ತು ಬೆಳಕು'),
        summary=W('Count the oxygen bubbles from a water plant as a lamp is moved closer, and find the limiting factor.', 'लैम्प को पास लाते हुए जलीय पौधे से निकलते ऑक्सीजन बुलबुले गिनें और सीमाकारी कारक ज्ञात करें।', 'ದೀಪವನ್ನು ಹತ್ತಿರ ತರುತ್ತಾ ಜಲಸಸ್ಯದಿಂದ ಬರುವ ಆಮ್ಲಜನಕ ಗುಳ್ಳೆಗಳನ್ನು ಎಣಿಸಿ, ಮಿತಿಗೊಳಿಸುವ ಅಂಶ ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To study the effect of light intensity, carbon dioxide and temperature on the rate of photosynthesis.', 'प्रकाश की तीव्रता, कार्बन डाइऑक्साइड और ताप का प्रकाश संश्लेषण की दर पर प्रभाव का अध्ययन करना।', 'ಬೆಳಕಿನ ತೀವ್ರತೆ, ಇಂಗಾಲದ ಡೈಆಕ್ಸೈಡ್ ಮತ್ತು ತಾಪ ದ್ಯುತಿಸಂಶ್ಲೇಷಣೆಯ ದರದ ಮೇಲೆ ಬೀರುವ ಪರಿಣಾಮ ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
        principle=W('A water plant gives off oxygen bubbles as it photosynthesises, so bubbles per minute measure the rate. Light intensity falls as 1/d² with the lamp distance d. The rate rises with light until another factor (carbon dioxide, from sodium bicarbonate, or temperature) runs short: the law of limiting factors.', 'जलीय पौधा प्रकाश संश्लेषण करते समय ऑक्सीजन बुलबुले छोड़ता है, इसलिए प्रति मिनट बुलबुले दर मापते हैं। प्रकाश की तीव्रता लैम्प की दूरी d के साथ 1/d² के अनुसार घटती है। दर प्रकाश के साथ तब तक बढ़ती है जब तक कोई दूसरा कारक (सोडियम बाइकार्बोनेट से कार्बन डाइऑक्साइड, या ताप) कम न पड़ जाए: सीमाकारी कारकों का नियम।', 'ಜಲಸಸ್ಯ ದ್ಯುತಿಸಂಶ್ಲೇಷಣೆ ಮಾಡುವಾಗ ಆಮ್ಲಜನಕ ಗುಳ್ಳೆಗಳನ್ನು ಬಿಡುತ್ತದೆ; ಆದ್ದರಿಂದ ನಿಮಿಷಕ್ಕೆ ಗುಳ್ಳೆಗಳು ದರವನ್ನು ಅಳೆಯುತ್ತವೆ. ಬೆಳಕಿನ ತೀವ್ರತೆ ದೀಪದ ದೂರ d ಯೊಂದಿಗೆ 1/d² ಆಗಿ ಇಳಿಯುತ್ತದೆ. ಇನ್ನೊಂದು ಅಂಶ (ಸೋಡಿಯಂ ಬೈಕಾರ್ಬೊನೇಟ್‌ನಿಂದ ಇಂಗಾಲದ ಡೈಆಕ್ಸೈಡ್, ಅಥವಾ ತಾಪ) ಕೊರತೆಯಾಗುವವರೆಗೆ ದರ ಬೆಳಕಿನೊಂದಿಗೆ ಏರುತ್ತದೆ: ಮಿತಿಗೊಳಿಸುವ ಅಂಶಗಳ ನಿಯಮ.'),
        apparatus=[W('Hydrilla (or Elodea) twig, beaker, funnel and test tube', 'हाइड्रिला (या एलोडिया) की टहनी, बीकर, कीप और परखनली', 'ಹೈಡ್ರಿಲ್ಲಾ (ಅಥವಾ ಎಲೋಡಿಯಾ) ಕೊಂಬೆ, ಬೀಕರ್, ಆಲಿಕೆ ಮತ್ತು ಪರೀಕ್ಷಾ ನಳಿಕೆ'), W('Lamp and metre scale', 'लैम्प और मीटर पैमाना', 'ದೀಪ ಮತ್ತು ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿ'), W('Sodium bicarbonate, thermometer and stopwatch', 'सोडियम बाइकार्बोनेट, तापमापी और विराम घड़ी', 'ಸೋಡಿಯಂ ಬೈಕಾರ್ಬೊನೇಟ್, ಉಷ್ಣಮಾಪಕ ಮತ್ತು ನಿಲುಗಡಿಯಾರ')],
        steps=[W('Place the twig, cut end up, under the funnel in water with a little sodium bicarbonate.', 'टहनी को, कटा सिरा ऊपर रखकर, थोड़े सोडियम बाइकार्बोनेट वाले जल में कीप के नीचे रखें।', 'ಕೊಂಬೆಯನ್ನು ಕತ್ತರಿಸಿದ ತುದಿ ಮೇಲಾಗಿ, ಸ್ವಲ್ಪ ಸೋಡಿಯಂ ಬೈಕಾರ್ಬೊನೇಟ್ ಇರುವ ನೀರಿನಲ್ಲಿ ಆಲಿಕೆಯ ಕೆಳಗೆ ಇಡಿ.'),
               W('Put the lamp 50 cm away, wait two minutes, then count the bubbles in one minute.', 'लैम्प 50 cm दूर रखें, दो मिनट रुकें, फिर एक मिनट में बुलबुले गिनें।', 'ದೀಪವನ್ನು 50 cm ದೂರ ಇಟ್ಟು, ಎರಡು ನಿಮಿಷ ಕಾದು, ನಂತರ ಒಂದು ನಿಮಿಷದಲ್ಲಿ ಗುಳ್ಳೆಗಳನ್ನು ಎಣಿಸಿ.'),
               W('Move the lamp closer in steps of 5 cm, counting at each distance.', 'लैम्प को 5 cm के चरणों में पास लाएँ और हर दूरी पर गिनें।', 'ದೀಪವನ್ನು 5 cm ಹೆಜ್ಜೆಗಳಲ್ಲಿ ಹತ್ತಿರ ತಂದು ಪ್ರತಿ ದೂರದಲ್ಲಿ ಎಣಿಸಿ.'),
               W('Plot bubbles per minute against 1000/d²; repeat with more bicarbonate and at another temperature.', '1000/d² के विरुद्ध प्रति मिनट बुलबुले आलेखित करें; अधिक बाइकार्बोनेट और दूसरे ताप पर दोहराएँ।', '1000/d² ವಿರುದ್ಧ ನಿಮಿಷಕ್ಕೆ ಗುಳ್ಳೆಗಳನ್ನು ನಕ್ಷೆ ಮಾಡಿ; ಹೆಚ್ಚು ಬೈಕಾರ್ಬೊನೇಟ್ ಮತ್ತು ಬೇರೆ ತಾಪದಲ್ಲಿ ಪುನರಾವರ್ತಿಸಿ.')],
        precautions=[W('Keep the water temperature steady: a lamp close to the beaker also heats it (use a heat screen).', 'जल का ताप स्थिर रखें: बीकर के पास लैम्प उसे गरम भी करता है (ऊष्मा परदा लगाएँ)।', 'ನೀರಿನ ತಾಪ ಸ್ಥಿರವಾಗಿಡಿ: ಬೀಕರ್ ಹತ್ತಿರದ ದೀಪ ಅದನ್ನು ಬಿಸಿಯೂ ಮಾಡುತ್ತದೆ (ಶಾಖ ಪರದೆ ಬಳಸಿ).'), W('Work in a dark room so the lamp is the only light.', 'अँधेरे कमरे में काम करें ताकि लैम्प ही एकमात्र प्रकाश हो।', 'ದೀಪವೇ ಏಕೈಕ ಬೆಳಕಾಗುವಂತೆ ಕತ್ತಲೆ ಕೋಣೆಯಲ್ಲಿ ಕೆಲಸ ಮಾಡಿ.')],
        conclusion=W('The rate of photosynthesis increases with light intensity and then levels off when carbon dioxide or temperature becomes limiting.', 'प्रकाश संश्लेषण की दर प्रकाश की तीव्रता के साथ बढ़ती है और फिर स्थिर हो जाती है जब कार्बन डाइऑक्साइड या ताप सीमाकारी बन जाता है।', 'ದ್ಯುತಿಸಂಶ್ಲೇಷಣೆಯ ದರ ಬೆಳಕಿನ ತೀವ್ರತೆಯೊಂದಿಗೆ ಏರುತ್ತದೆ, ನಂತರ ಇಂಗಾಲದ ಡೈಆಕ್ಸೈಡ್ ಅಥವಾ ತಾಪ ಮಿತಿಗೊಳಿಸಿದಾಗ ಸ್ಥಿರವಾಗುತ್ತದೆ.'),
        viva=[Q(W('Which gas is in the bubbles?', 'बुलबुलों में कौन-सी गैस है?', 'ಗುಳ್ಳೆಗಳಲ್ಲಿ ಯಾವ ಅನಿಲ?'), W('Mainly oxygen; it relights a glowing splint.', 'मुख्यतः ऑक्सीजन; यह सुलगती तीली को फिर जला देती है।', 'ಮುಖ್ಯವಾಗಿ ಆಮ್ಲಜನಕ; ಅದು ಹೊಗೆಯಾಡುವ ಕಡ್ಡಿಯನ್ನು ಮತ್ತೆ ಉರಿಸುತ್ತದೆ.')),
              Q(W('Why add sodium bicarbonate?', 'सोडियम बाइकार्बोनेट क्यों मिलाते हैं?', 'ಸೋಡಿಯಂ ಬೈಕಾರ್ಬೊನೇಟ್ ಏಕೆ ಸೇರಿಸುತ್ತಾರೆ?'), W('It supplies carbon dioxide to the water.', 'यह जल को कार्बन डाइऑक्साइड देता है।', 'ಅದು ನೀರಿಗೆ ಇಂಗಾಲದ ಡೈಆಕ್ಸೈಡ್ ಒದಗಿಸುತ್ತದೆ.')),
              Q(W('Who stated the law of limiting factors?', 'सीमाकारी कारकों का नियम किसने दिया?', 'ಮಿತಿಗೊಳಿಸುವ ಅಂಶಗಳ ನಿಯಮ ಯಾರು ನೀಡಿದರು?'), W('F. F. Blackman (1905).', 'एफ़. एफ़. ब्लैकमैन (1905)।', 'ಎಫ್. ಎಫ್. ಬ್ಲ್ಯಾಕ್‌ಮನ್ (1905).'))])

    lab(id='enzyme-amylase', bench='amylase', levels=[11, 12, 'ug'], curricula=['cbse', 'ncert', 'ka-puc', 'ug-biology'], **bio,
        keywords=['enzyme', 'salivary amylase', 'starch', 'iodine', 'temperature', 'pH', 'denaturation', 'digestion'],
        title=W('Effect of temperature and pH on salivary amylase', 'लार एमाइलेज़ पर ताप और pH का प्रभाव', 'ಲಾಲಾರಸದ ಅಮೈಲೇಸ್ ಮೇಲೆ ತಾಪ ಮತ್ತು pH ಪರಿಣಾಮ'),
        summary=W('Time how long amylase takes to digest starch at different temperatures and pH values, using iodine.', 'आयोडीन से देखें कि विभिन्न ताप और pH पर एमाइलेज़ स्टार्च को पचाने में कितना समय लेता है।', 'ಬೇರೆ ಬೇರೆ ತಾಪ ಮತ್ತು pH ಗಳಲ್ಲಿ ಅಮೈಲೇಸ್ ಪಿಷ್ಟ ಜೀರ್ಣಿಸಲು ಎಷ್ಟು ಸಮಯ ತೆಗೆದುಕೊಳ್ಳುತ್ತದೆ ಎಂದು ಅಯೋಡಿನ್ ಬಳಸಿ ಅಳೆಯಿರಿ.'),
        aim=W('To study the effect of temperature and pH on the activity of salivary amylase on starch.', 'स्टार्च पर लार एमाइलेज़ की सक्रियता पर ताप और pH के प्रभाव का अध्ययन करना।', 'ಪಿಷ್ಟದ ಮೇಲೆ ಲಾಲಾರಸದ ಅಮೈಲೇಸ್ ಚಟುವಟಿಕೆಗೆ ತಾಪ ಮತ್ತು pH ನ ಪರಿಣಾಮ ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
        principle=W('Amylase breaks starch into maltose. Starch gives a blue-black colour with iodine; when it is all digested (the achromic point) the iodine stays yellow-brown. The time t to that point is short when the enzyme is fast: rate ∝ 1/t. Enzymes speed up with warmth, are destroyed (denatured) above about 45 °C, and work best at one pH.', 'एमाइलेज़ स्टार्च को माल्टोज़ में तोड़ता है। स्टार्च आयोडीन के साथ नीला-काला रंग देता है; जब सब पच जाता है (अवर्णी बिंदु) तो आयोडीन पीला-भूरा रहता है। उस बिंदु तक का समय t एंज़ाइम तेज़ हो तो कम होता है: दर ∝ 1/t। एंज़ाइम गर्मी से तेज़ होते हैं, लगभग 45 °C से ऊपर नष्ट (विकृत) हो जाते हैं, और एक pH पर सबसे अच्छा काम करते हैं।', 'ಅಮೈಲೇಸ್ ಪಿಷ್ಟವನ್ನು ಮಾಲ್ಟೋಸ್ ಆಗಿ ಒಡೆಯುತ್ತದೆ. ಪಿಷ್ಟ ಅಯೋಡಿನ್‌ನೊಂದಿಗೆ ನೀಲಿ-ಕಪ್ಪು ಬಣ್ಣ ನೀಡುತ್ತದೆ; ಎಲ್ಲವೂ ಜೀರ್ಣವಾದಾಗ (ವರ್ಣರಹಿತ ಬಿಂದು) ಅಯೋಡಿನ್ ಹಳದಿ-ಕಂದು ಉಳಿಯುತ್ತದೆ. ಕಿಣ್ವ ವೇಗವಾಗಿದ್ದರೆ ಆ ಬಿಂದುವಿನವರೆಗಿನ ಸಮಯ t ಕಡಿಮೆ: ದರ ∝ 1/t. ಕಿಣ್ವಗಳು ಬಿಸಿಯಿಂದ ವೇಗವಾಗುತ್ತವೆ, ಸುಮಾರು 45 °C ಮೇಲೆ ನಾಶವಾಗುತ್ತವೆ (ವಿಕೃತಿ), ಮತ್ತು ಒಂದು pH ನಲ್ಲಿ ಅತ್ಯುತ್ತಮವಾಗಿ ಕೆಲಸ ಮಾಡುತ್ತವೆ.'),
        apparatus=[W('1 % starch solution, diluted saliva and buffer solutions', '1 % स्टार्च विलयन, तनु लार और बफ़र विलयन', '1 % ಪಿಷ್ಟ ದ್ರಾವಣ, ವಿರಳ ಲಾಲಾರಸ ಮತ್ತು ಬಫರ್ ದ್ರಾವಣಗಳು'), W('Iodine solution and a white spotting tile', 'आयोडीन विलयन और सफ़ेद स्पॉटिंग टाइल', 'ಅಯೋಡಿನ್ ದ್ರಾವಣ ಮತ್ತು ಬಿಳಿ ಚುಕ್ಕೆ ಟೈಲ್'), W('Water baths, test tubes, dropper and stopwatch', 'जल ऊष्मक, परखनलियाँ, ड्रॉपर और विराम घड़ी', 'ನೀರಿನ ತೊಟ್ಟಿಗಳು, ಪರೀಕ್ಷಾ ನಳಿಕೆಗಳು, ಡ್ರಾಪರ್ ಮತ್ತು ನಿಲುಗಡಿಯಾರ')],
        steps=[W('Put a drop of iodine in each well of the tile.', 'टाइल के हर गड्ढे में आयोडीन की एक बूँद डालें।', 'ಟೈಲ್‌ನ ಪ್ರತಿ ಕುಳಿಗೆ ಅಯೋಡಿನ್‌ನ ಒಂದು ಹನಿ ಹಾಕಿ.'),
               W('Warm starch with buffer, and the saliva, separately in the water bath for five minutes.', 'स्टार्च को बफ़र के साथ, और लार को, अलग-अलग जल ऊष्मक में पाँच मिनट गरम करें।', 'ಪಿಷ್ಟವನ್ನು ಬಫರ್‌ನೊಂದಿಗೆ ಮತ್ತು ಲಾಲಾರಸವನ್ನು ಬೇರೆಯಾಗಿ ನೀರಿನ ತೊಟ್ಟಿಯಲ್ಲಿ ಐದು ನಿಮಿಷ ಬಿಸಿಮಾಡಿ.'),
               W('Mix them, start the clock, and every 30 s put a drop of the mixture on fresh iodine.', 'उन्हें मिलाएँ, घड़ी चलाएँ, और हर 30 s पर मिश्रण की एक बूँद ताज़े आयोडीन पर डालें।', 'ಅವುಗಳನ್ನು ಬೆರೆಸಿ, ಗಡಿಯಾರ ಆರಂಭಿಸಿ, ಪ್ರತಿ 30 s ಗೆ ಮಿಶ್ರಣದ ಒಂದು ಹನಿಯನ್ನು ಹೊಸ ಅಯೋಡಿನ್ ಮೇಲೆ ಹಾಕಿ.'),
               W('Note the time when the iodine no longer turns blue-black; repeat at other temperatures and pH values.', 'वह समय लिखें जब आयोडीन नीला-काला नहीं होता; अन्य ताप और pH पर दोहराएँ।', 'ಅಯೋಡಿನ್ ಇನ್ನು ನೀಲಿ-ಕಪ್ಪಾಗದ ಸಮಯ ಬರೆಯಿರಿ; ಬೇರೆ ತಾಪ ಮತ್ತು pH ಗಳಲ್ಲಿ ಪುನರಾವರ್ತಿಸಿ.')],
        precautions=[W('Use the same volumes of starch, saliva and buffer every time.', 'हर बार स्टार्च, लार और बफ़र के समान आयतन लें।', 'ಪ್ರತಿ ಬಾರಿ ಪಿಷ್ಟ, ಲಾಲಾರಸ ಮತ್ತು ಬಫರ್‌ನ ಸಮಾನ ಘನಫಲ ಬಳಸಿ.'), W('Use a clean dropper so starch is not carried into the iodine.', 'साफ़ ड्रॉपर लें ताकि स्टार्च आयोडीन में न जाए।', 'ಪಿಷ್ಟ ಅಯೋಡಿನ್‌ಗೆ ಸಾಗದಂತೆ ಸ್ವಚ್ಛ ಡ್ರಾಪರ್ ಬಳಸಿ.')],
        conclusion=W('Salivary amylase works fastest near body temperature and pH 6.8; it is slow in the cold and stops working when heated above about 50 °C or in acid.', 'लार एमाइलेज़ शरीर के ताप और pH 6.8 के पास सबसे तेज़ काम करता है; ठंड में धीमा होता है और लगभग 50 °C से अधिक गरम करने पर या अम्ल में काम करना बंद कर देता है।', 'ಲಾಲಾರಸದ ಅಮೈಲೇಸ್ ದೇಹದ ತಾಪ ಮತ್ತು pH 6.8 ಬಳಿ ಅತ್ಯಂತ ವೇಗವಾಗಿ ಕೆಲಸ ಮಾಡುತ್ತದೆ; ಚಳಿಯಲ್ಲಿ ನಿಧಾನ, ಸುಮಾರು 50 °C ಮೇಲೆ ಬಿಸಿಮಾಡಿದಾಗ ಅಥವಾ ಆಮ್ಲದಲ್ಲಿ ಕೆಲಸ ನಿಲ್ಲಿಸುತ್ತದೆ.'),
        viva=[Q(W('What is the product of starch digestion by amylase?', 'एमाइलेज़ द्वारा स्टार्च पाचन का उत्पाद क्या है?', 'ಅಮೈಲೇಸ್‌ನಿಂದ ಪಿಷ್ಟ ಜೀರ್ಣದ ಉತ್ಪನ್ನ ಯಾವುದು?'), W('Maltose (a reducing sugar).', 'माल्टोज़ (एक अपचायी शर्करा)।', 'ಮಾಲ್ಟೋಸ್ (ಒಂದು ಅಪಕರ್ಷಕ ಸಕ್ಕರೆ).')),
              Q(W('Why does the enzyme stop working at high temperature?', 'उच्च ताप पर एंज़ाइम काम करना क्यों बंद कर देता है?', 'ಹೆಚ್ಚಿನ ತಾಪದಲ್ಲಿ ಕಿಣ್ವ ಕೆಲಸ ಏಕೆ ನಿಲ್ಲಿಸುತ್ತದೆ?'), W('Its protein chain unfolds, so the active site loses its shape (denaturation).', 'इसकी प्रोटीन शृंखला खुल जाती है, जिससे सक्रिय स्थल का आकार बिगड़ जाता है (विकृतीकरण)।', 'ಅದರ ಪ್ರೋಟೀನ್ ಸರಪಳಿ ಬಿಚ್ಚಿಕೊಳ್ಳುತ್ತದೆ; ಸಕ್ರಿಯ ತಾಣ ಆಕಾರ ಕಳೆದುಕೊಳ್ಳುತ್ತದೆ (ವಿಕೃತಿ).')),
              Q(W('Why does amylase stop working in the stomach?', 'आमाशय में एमाइलेज़ काम करना क्यों बंद कर देता है?', 'ಜಠರದಲ್ಲಿ ಅಮೈಲೇಸ್ ಏಕೆ ಕೆಲಸ ನಿಲ್ಲಿಸುತ್ತದೆ?'), W('The stomach is strongly acidic (pH about 2), far from its optimum.', 'आमाशय तीव्र अम्लीय है (pH लगभग 2), जो इसके इष्टतम से बहुत दूर है।', 'ಜಠರ ತೀವ್ರ ಆಮ್ಲೀಯ (pH ಸುಮಾರು 2), ಅದರ ಅನುಕೂಲತಮ pH ನಿಂದ ಬಹಳ ದೂರ.'))])

    ug = dict(curricula=['ug-biology', 'ug-biotechnology'], **bio)

    lab(id='michaelis-menten', bench='michaelis', levels=['ug', 'pg'], **ug,
        keywords=['enzyme kinetics', 'michaelis menten', 'lineweaver burk', 'km', 'vmax', 'competitive inhibition', 'non-competitive inhibition'],
        title=W('Enzyme kinetics: Km and Vmax', 'एंज़ाइम गतिकी: Km और Vmax', 'ಕಿಣ್ವ ಚಲನಶಾಸ್ತ್ರ: Km ಮತ್ತು Vmax'),
        summary=W('Measure initial rates at several substrate concentrations, with and without inhibitors, and fit a Lineweaver–Burk plot.', 'कई सब्सट्रेट सांद्रताओं पर, अवरोधक सहित और रहित, प्रारंभिक दरें मापें और लाइनवीवर–बर्क आलेख फ़िट करें।', 'ಹಲವು ತಲಾಧಾರ ಸಾಂದ್ರತೆಗಳಲ್ಲಿ, ಪ್ರತಿಬಂಧಕ ಸಹಿತ ಮತ್ತು ರಹಿತ, ಆರಂಭಿಕ ದರಗಳನ್ನು ಅಳೆದು ಲೈನ್‌ವೀವರ್–ಬರ್ಕ್ ನಕ್ಷೆ ಹೊಂದಿಸಿ.'),
        aim=W('To find Km and Vmax of an enzyme and tell competitive from non-competitive inhibition.', 'एक एंज़ाइम का Km और Vmax ज्ञात करना और प्रतिस्पर्धी तथा अप्रतिस्पर्धी अवरोधन में भेद करना।', 'ಒಂದು ಕಿಣ್ವದ Km ಮತ್ತು Vmax ಕಂಡುಹಿಡಿದು ಸ್ಪರ್ಧಾತ್ಮಕ ಮತ್ತು ಅಸ್ಪರ್ಧಾತ್ಮಕ ಪ್ರತಿಬಂಧವನ್ನು ಬೇರ್ಪಡಿಸುವುದು.'),
        principle=W('v₀ = Vmax[S] ÷ (Km + [S]). Inverting gives a straight line, 1/v₀ = (Km/Vmax)(1/[S]) + 1/Vmax, so the intercept gives Vmax and slope ÷ intercept gives Km, each with an uncertainty from the fit. A competitive inhibitor raises the apparent Km only; a non-competitive one lowers Vmax only.', 'v₀ = Vmax[S] ÷ (Km + [S])। उलटने पर सीधी रेखा मिलती है, 1/v₀ = (Km/Vmax)(1/[S]) + 1/Vmax, अतः अंतःखंड से Vmax और ढाल ÷ अंतःखंड से Km मिलता है, दोनों फ़िट से अनिश्चितता सहित। प्रतिस्पर्धी अवरोधक केवल आभासी Km बढ़ाता है; अप्रतिस्पर्धी केवल Vmax घटाता है।', 'v₀ = Vmax[S] ÷ (Km + [S]). ತಿರುಗಿಸಿದರೆ ನೇರ ರೇಖೆ: 1/v₀ = (Km/Vmax)(1/[S]) + 1/Vmax; ಆದ್ದರಿಂದ ಅಂತಃಖಂಡ Vmax ನೀಡುತ್ತದೆ, ಇಳಿಜಾರು ÷ ಅಂತಃಖಂಡ Km ನೀಡುತ್ತದೆ, ಎರಡೂ ಹೊಂದಿಕೆಯಿಂದ ಅನಿಶ್ಚಿತತೆಯೊಂದಿಗೆ. ಸ್ಪರ್ಧಾತ್ಮಕ ಪ್ರತಿಬಂಧಕ ತೋರಿಕೆಯ Km ಅನ್ನು ಮಾತ್ರ ಹೆಚ್ಚಿಸುತ್ತದೆ; ಅಸ್ಪರ್ಧಾತ್ಮಕ Vmax ಅನ್ನು ಮಾತ್ರ ಇಳಿಸುತ್ತದೆ.'),
        apparatus=[W('Spectrophotometer and cuvettes', 'स्पेक्ट्रोफ़ोटोमीटर और क्यूवेट', 'ಸ್ಪೆಕ್ಟ್ರೋಫೋಟೋಮೀಟರ್ ಮತ್ತು ಕ್ಯುವೆಟ್‌ಗಳು'), W('Enzyme, substrate dilutions and inhibitor solutions', 'एंज़ाइम, सब्सट्रेट के तनु विलयन और अवरोधक विलयन', 'ಕಿಣ್ವ, ತಲಾಧಾರ ವಿರಳನಗಳು ಮತ್ತು ಪ್ರತಿಬಂಧಕ ದ್ರಾವಣಗಳು'), W('Micropipettes and a timer', 'माइक्रोपिपेट और टाइमर', 'ಮೈಕ್ರೋಪಿಪೆಟ್‌ಗಳು ಮತ್ತು ಟೈಮರ್')],
        steps=[W('Make substrate solutions from 0.5 to 32 mM in buffer.', 'बफ़र में 0.5 से 32 mM तक सब्सट्रेट विलयन बनाएँ।', 'ಬಫರ್‌ನಲ್ಲಿ 0.5 ರಿಂದ 32 mM ವರೆಗೆ ತಲಾಧಾರ ದ್ರಾವಣಗಳನ್ನು ತಯಾರಿಸಿ.'),
               W('Start each reaction with the same amount of enzyme and record the absorbance for the first minute.', 'हर अभिक्रिया समान मात्रा के एंज़ाइम से शुरू करें और पहले मिनट का अवशोषणांक दर्ज करें।', 'ಪ್ರತಿ ಪ್ರತಿಕ್ರಿಯೆಯನ್ನು ಸಮಾನ ಪ್ರಮಾಣದ ಕಿಣ್ವದಿಂದ ಆರಂಭಿಸಿ ಮೊದಲ ನಿಮಿಷದ ಹೀರಿಕೆ ದಾಖಲಿಸಿ.'),
               W('Convert the initial slope to v₀ and record 1/[S] and 1/v₀.', 'प्रारंभिक ढाल को v₀ में बदलें और 1/[S] तथा 1/v₀ दर्ज करें।', 'ಆರಂಭಿಕ ಇಳಿಜಾರನ್ನು v₀ ಆಗಿ ಪರಿವರ್ತಿಸಿ 1/[S] ಮತ್ತು 1/v₀ ದಾಖಲಿಸಿ.'),
               W('Repeat the series with each inhibitor; fit straight lines and compare Km and Vmax.', 'हर अवरोधक के साथ शृंखला दोहराएँ; सीधी रेखाएँ फ़िट करें और Km तथा Vmax की तुलना करें।', 'ಪ್ರತಿ ಪ್ರತಿಬಂಧಕದೊಂದಿಗೆ ಸರಣಿ ಪುನರಾವರ್ತಿಸಿ; ನೇರ ರೇಖೆಗಳನ್ನು ಹೊಂದಿಸಿ Km ಮತ್ತು Vmax ಹೋಲಿಸಿ.')],
        precautions=[W('Measure only the initial rate, before much substrate is used.', 'केवल प्रारंभिक दर मापें, इससे पहले कि अधिक सब्सट्रेट खप जाए।', 'ಹೆಚ್ಚು ತಲಾಧಾರ ಬಳಕೆಯಾಗುವ ಮೊದಲು ಆರಂಭಿಕ ದರವನ್ನು ಮಾತ್ರ ಅಳೆಯಿರಿ.'), W('Keep temperature and pH constant for every run.', 'हर बार ताप और pH स्थिर रखें।', 'ಪ್ರತಿ ಬಾರಿ ತಾಪ ಮತ್ತು pH ಸ್ಥಿರವಾಗಿಡಿ.'), W('Export the readings as CSV to fit the lines with weights if needed.', 'आवश्यक हो तो भारित फ़िट के लिए पाठ्यांक CSV में निर्यात करें।', 'ಅಗತ್ಯವಿದ್ದರೆ ತೂಕಸಹಿತ ಹೊಂದಿಕೆಗೆ ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ.')],
        conclusion=W('The enzyme has Km of about 4 mM and Vmax of about 120 µmol/min; the competitive inhibitor raises Km and the non-competitive one lowers Vmax.', 'एंज़ाइम का Km लगभग 4 mM और Vmax लगभग 120 µmol/min है; प्रतिस्पर्धी अवरोधक Km बढ़ाता है और अप्रतिस्पर्धी Vmax घटाता है।', 'ಕಿಣ್ವದ Km ಸುಮಾರು 4 mM ಮತ್ತು Vmax ಸುಮಾರು 120 µmol/min; ಸ್ಪರ್ಧಾತ್ಮಕ ಪ್ರತಿಬಂಧಕ Km ಏರಿಸುತ್ತದೆ, ಅಸ್ಪರ್ಧಾತ್ಮಕ Vmax ಇಳಿಸುತ್ತದೆ.'),
        viva=[Q(W('What does Km mean?', 'Km का क्या अर्थ है?', 'Km ಎಂದರೇನು?'), W('The substrate concentration at which the rate is half of Vmax; a low Km means high affinity.', 'वह सब्सट्रेट सांद्रता जिस पर दर Vmax की आधी है; कम Km का अर्थ उच्च बंधुता।', 'ದರ Vmax ನ ಅರ್ಧವಾಗುವ ತಲಾಧಾರ ಸಾಂದ್ರತೆ; ಕಡಿಮೆ Km ಎಂದರೆ ಹೆಚ್ಚಿನ ಆಕರ್ಷಣೆ.')),
              Q(W('What is a drawback of the Lineweaver–Burk plot?', 'लाइनवीवर–बर्क आलेख की एक कमी क्या है?', 'ಲೈನ್‌ವೀವರ್–ಬರ್ಕ್ ನಕ್ಷೆಯ ಒಂದು ಕೊರತೆ ಏನು?'), W('It stretches the errors of the slowest rates (small [S]), which dominate the fit.', 'यह सबसे धीमी दरों (कम [S]) की त्रुटियों को खींचकर बढ़ा देता है, जो फ़िट पर हावी हो जाती हैं।', 'ಅದು ಅತಿ ನಿಧಾನ ದರಗಳ (ಕಡಿಮೆ [S]) ದೋಷಗಳನ್ನು ವಿಸ್ತರಿಸುತ್ತದೆ; ಅವು ಹೊಂದಿಕೆಯನ್ನು ಆಳುತ್ತವೆ.')),
              Q(W('How can competitive inhibition be overcome?', 'प्रतिस्पर्धी अवरोधन को कैसे दूर किया जा सकता है?', 'ಸ್ಪರ್ಧಾತ್ಮಕ ಪ್ರತಿಬಂಧವನ್ನು ಹೇಗೆ ಮೀರಬಹುದು?'), W('By raising the substrate concentration, which outcompetes the inhibitor.', 'सब्सट्रेट सांद्रता बढ़ाकर, जो अवरोधक से प्रतिस्पर्धा जीत लेता है।', 'ತಲಾಧಾರ ಸಾಂದ್ರತೆ ಹೆಚ್ಚಿಸುವ ಮೂಲಕ; ಅದು ಪ್ರತಿಬಂಧಕವನ್ನು ಸ್ಪರ್ಧೆಯಲ್ಲಿ ಮೀರಿಸುತ್ತದೆ.'))])

    lab(id='microbial-growth', bench='growth', levels=['ug', 'pg'], curricula=['ug-biology', 'ug-microbiology'], **bio,
        keywords=['bacterial growth curve', 'microbiology', 'optical density', 'generation time', 'lag phase', 'log phase', 'stationary phase'],
        title=W('Bacterial growth curve', 'जीवाणु वृद्धि वक्र', 'ಬ್ಯಾಕ್ಟೀರಿಯಾ ಬೆಳವಣಿಗೆ ವಕ್ರ'),
        summary=W('Follow the optical density of a culture over 14 hours at different temperatures and find the generation time.', 'विभिन्न तापों पर 14 घंटे तक संवर्धन का प्रकाशिक घनत्व देखें और पीढ़ी काल ज्ञात करें।', 'ಬೇರೆ ಬೇರೆ ತಾಪಗಳಲ್ಲಿ 14 ಗಂಟೆಗಳವರೆಗೆ ಸಂವರ್ಧನೆಯ ದೃಕ್ ಸಾಂದ್ರತೆ ಗಮನಿಸಿ ಪೀಳಿಗೆ ಸಮಯ ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To plot the growth curve of a bacterial culture and find its specific growth rate and generation time.', 'जीवाणु संवर्धन का वृद्धि वक्र आलेखित करना और उसकी विशिष्ट वृद्धि दर तथा पीढ़ी काल ज्ञात करना।', 'ಬ್ಯಾಕ್ಟೀರಿಯಾ ಸಂವರ್ಧನೆಯ ಬೆಳವಣಿಗೆ ವಕ್ರ ರಚಿಸಿ ಅದರ ವಿಶಿಷ್ಟ ಬೆಳವಣಿಗೆ ದರ ಮತ್ತು ಪೀಳಿಗೆ ಸಮಯ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('In a batch culture bacteria pass through lag, log (exponential), stationary and death phases. Optical density at 600 nm is proportional to cell number while it is low. In the log phase ln OD rises in a straight line with slope μ, the specific growth rate; the generation (doubling) time is g = ln 2 ÷ μ.', 'बैच संवर्धन में जीवाणु पश्चता, लघुगणकीय (घातांकी), स्थिर और मृत्यु प्रावस्थाओं से गुज़रते हैं। 600 nm पर प्रकाशिक घनत्व कम रहने तक कोशिका संख्या के समानुपाती होता है। लघुगणकीय प्रावस्था में ln OD ढाल μ (विशिष्ट वृद्धि दर) के साथ सीधी रेखा में बढ़ता है; पीढ़ी (द्विगुणन) काल g = ln 2 ÷ μ।', 'ಬ್ಯಾಚ್ ಸಂವರ್ಧನೆಯಲ್ಲಿ ಬ್ಯಾಕ್ಟೀರಿಯಾ ವಿಳಂಬ, ಲಘುಗಣಕ (ಘಾತೀಯ), ಸ್ಥಿರ ಮತ್ತು ಮರಣ ಹಂತಗಳನ್ನು ದಾಟುತ್ತವೆ. 600 nm ನಲ್ಲಿ ದೃಕ್ ಸಾಂದ್ರತೆ ಕಡಿಮೆ ಇರುವವರೆಗೆ ಕೋಶ ಸಂಖ್ಯೆಗೆ ಅನುಪಾತೀಯ. ಲಘುಗಣಕ ಹಂತದಲ್ಲಿ ln OD ಇಳಿಜಾರು μ (ವಿಶಿಷ್ಟ ಬೆಳವಣಿಗೆ ದರ) ದೊಂದಿಗೆ ನೇರ ರೇಖೆಯಲ್ಲಿ ಏರುತ್ತದೆ; ಪೀಳಿಗೆ (ದ್ವಿಗುಣ) ಸಮಯ g = ln 2 ÷ μ.'),
        apparatus=[W('Nutrient broth culture of E. coli', 'ई. कोलाई का पोषक शोरबा संवर्धन', 'ಇ. ಕೋಲೈನ ಪೋಷಕ ಸಾರು ಸಂವರ್ಧನೆ'), W('Shaking incubator and spectrophotometer (600 nm)', 'हिलाने वाला इनक्यूबेटर और स्पेक्ट्रोफ़ोटोमीटर (600 nm)', 'ಅಲುಗಾಡಿಸುವ ಇನ್‌ಕ್ಯುಬೇಟರ್ ಮತ್ತು ಸ್ಪೆಕ್ಟ್ರೋಫೋಟೋಮೀಟರ್ (600 nm)'), W('Sterile pipettes, cuvettes and a laminar flow hood', 'निर्जीवाणुकृत पिपेट, क्यूवेट और लैमिनार फ़्लो हुड', 'ನಿರ್ಜೀವೀಕೃತ ಪಿಪೆಟ್‌ಗಳು, ಕ್ಯುವೆಟ್‌ಗಳು ಮತ್ತು ಲ್ಯಾಮಿನಾರ್ ಫ್ಲೋ ಹುಡ್')],
        steps=[W('Inoculate fresh broth with 1 % of an overnight culture and set the incubator temperature.', 'ताज़े शोरबे में रात भर के संवर्धन का 1 % डालें और इनक्यूबेटर का ताप तय करें।', 'ಹೊಸ ಸಾರಿಗೆ ರಾತ್ರಿಯ ಸಂವರ್ಧನೆಯ 1 % ಸೇರಿಸಿ ಇನ್‌ಕ್ಯುಬೇಟರ್ ತಾಪ ನಿಗದಿಪಡಿಸಿ.'),
               W('Every half hour take a sample aseptically and read its OD at 600 nm against sterile broth.', 'हर आधे घंटे पर अपूतित रूप से नमूना लें और निर्जीवाणु शोरबे के सापेक्ष 600 nm पर OD पढ़ें।', 'ಪ್ರತಿ ಅರ್ಧ ಗಂಟೆಗೆ ಅಸೆಪ್ಟಿಕ್ ಆಗಿ ಮಾದರಿ ತೆಗೆದು ನಿರ್ಜೀವ ಸಾರಿನ ಎದುರು 600 nm ನಲ್ಲಿ OD ಓದಿ.'),
               W('Plot ln OD against time and mark the lag, log and stationary phases.', 'समय के विरुद्ध ln OD आलेखित करें और पश्चता, लघुगणकीय और स्थिर प्रावस्थाएँ चिह्नित करें।', 'ಸಮಯದ ವಿರುದ್ಧ ln OD ನಕ್ಷೆ ಮಾಡಿ ವಿಳಂಬ, ಲಘುಗಣಕ ಮತ್ತು ಸ್ಥಿರ ಹಂತಗಳನ್ನು ಗುರುತಿಸಿ.'),
               W('Fit the straight part to find μ and the generation time; repeat at other temperatures.', 'μ और पीढ़ी काल के लिए सीधा भाग फ़िट करें; अन्य तापों पर दोहराएँ।', 'μ ಮತ್ತು ಪೀಳಿಗೆ ಸಮಯಕ್ಕಾಗಿ ನೇರ ಭಾಗವನ್ನು ಹೊಂದಿಸಿ; ಬೇರೆ ತಾಪಗಳಲ್ಲಿ ಪುನರಾವರ್ತಿಸಿ.')],
        precautions=[STERILE, W('Dilute samples whose OD is above 0.8 before reading, then multiply back.', '0.8 से अधिक OD वाले नमूनों को पढ़ने से पहले तनु करें, फिर वापस गुणा करें।', '0.8 ಕ್ಕಿಂತ ಹೆಚ್ಚು OD ಇರುವ ಮಾದರಿಗಳನ್ನು ಓದುವ ಮೊದಲು ವಿರಳಗೊಳಿಸಿ, ನಂತರ ಮರಳಿ ಗುಣಿಸಿ.')],
        conclusion=W('The culture shows lag, log and stationary phases; at 37 °C it doubles fastest (about every 45–50 minutes here) and growth is slow at 20 °C.', 'संवर्धन पश्चता, लघुगणकीय और स्थिर प्रावस्थाएँ दिखाता है; 37 °C पर यह सबसे तेज़ (यहाँ लगभग हर 45–50 मिनट) दुगुना होता है और 20 °C पर वृद्धि धीमी है।', 'ಸಂವರ್ಧನೆ ವಿಳಂಬ, ಲಘುಗಣಕ ಮತ್ತು ಸ್ಥಿರ ಹಂತಗಳನ್ನು ತೋರಿಸುತ್ತದೆ; 37 °C ನಲ್ಲಿ ಅತ್ಯಂತ ವೇಗವಾಗಿ (ಇಲ್ಲಿ ಸುಮಾರು 45–50 ನಿಮಿಷಕ್ಕೊಮ್ಮೆ) ದ್ವಿಗುಣವಾಗುತ್ತದೆ, 20 °C ನಲ್ಲಿ ಬೆಳವಣಿಗೆ ನಿಧಾನ.'),
        viva=[Q(W('What happens in the lag phase?', 'पश्चता प्रावस्था में क्या होता है?', 'ವಿಳಂಬ ಹಂತದಲ್ಲಿ ಏನಾಗುತ್ತದೆ?'), W('Cells adjust to the new medium, making enzymes, but hardly divide.', 'कोशिकाएँ नए माध्यम के अनुकूल होती हैं, एंज़ाइम बनाती हैं, पर लगभग विभाजित नहीं होतीं।', 'ಕೋಶಗಳು ಹೊಸ ಮಾಧ್ಯಮಕ್ಕೆ ಹೊಂದಿಕೊಳ್ಳುತ್ತವೆ, ಕಿಣ್ವ ತಯಾರಿಸುತ್ತವೆ, ಆದರೆ ಬಹುತೇಕ ವಿಭಜನೆಯಾಗುವುದಿಲ್ಲ.')),
              Q(W('Why does growth stop in the stationary phase?', 'स्थिर प्रावस्था में वृद्धि क्यों रुकती है?', 'ಸ್ಥಿರ ಹಂತದಲ್ಲಿ ಬೆಳವಣಿಗೆ ಏಕೆ ನಿಲ್ಲುತ್ತದೆ?'), W('Nutrients run out and waste products build up.', 'पोषक तत्व समाप्त होते हैं और अपशिष्ट जमा होते हैं।', 'ಪೋಷಕಾಂಶಗಳು ಮುಗಿಯುತ್ತವೆ ಮತ್ತು ತ್ಯಾಜ್ಯಗಳು ಸಂಗ್ರಹವಾಗುತ್ತವೆ.')),
              Q(W('Does OD count dead cells?', 'क्या OD मृत कोशिकाएँ भी गिनता है?', 'OD ಸತ್ತ ಕೋಶಗಳನ್ನೂ ಎಣಿಸುತ್ತದೆಯೇ?'), W('Yes: it measures turbidity, so a viable plate count is needed to count living cells.', 'हाँ: यह गंदलापन मापता है, इसलिए जीवित कोशिकाओं के लिए प्लेट गणना चाहिए।', 'ಹೌದು: ಅದು ಕಲಕತನ ಅಳೆಯುತ್ತದೆ; ಜೀವಂತ ಕೋಶಗಳಿಗೆ ಪ್ಲೇಟ್ ಎಣಿಕೆ ಬೇಕು.'))])

    CHI = W('Use the chi-square test: compare χ² with the table value for (classes − 1) degrees of freedom at 5 %.', 'काई-वर्ग परीक्षण करें: χ² की तुलना 5 % पर (वर्ग − 1) स्वातंत्र्य कोटि के सारणी मान से करें।', 'ಕೈ-ವರ್ಗ ಪರೀಕ್ಷೆ ಬಳಸಿ: χ² ಅನ್ನು 5 % ನಲ್ಲಿ (ವರ್ಗಗಳು − 1) ಸ್ವಾತಂತ್ರ್ಯ ಮಟ್ಟದ ಕೋಷ್ಟಕ ಮೌಲ್ಯದೊಂದಿಗೆ ಹೋಲಿಸಿ.')
    lab(id='monohybrid-cross', bench='cross', setup={'set': 'mono', 'cross': 'Aa×Aa'}, levels=[10, 12], curricula=['cbse', 'ncert', 'ka-sslc', 'ka-puc'], **bio,
        keywords=['monohybrid cross', 'mendel', 'heredity', 'punnett square', 'dominant', 'recessive', '3:1 ratio', 'chi square', 'test cross'],
        title=W("Mendel's monohybrid cross", 'मेंडल का एकसंकर संकरण', 'ಮೆಂಡಲ್‌ನ ಏಕಸಂಕರ ಸಂಕರಣ'),
        summary=W('Cross tall pea plants, count the offspring and test whether they fit 3 : 1 (or 1 : 1 in a test cross).', 'लंबे मटर के पौधों का संकरण करें, संतति गिनें और जाँचें कि वे 3 : 1 (या परीक्षण संकरण में 1 : 1) से मेल खाती हैं या नहीं।', 'ಎತ್ತರದ ಬಟಾಣಿ ಗಿಡಗಳನ್ನು ಸಂಕರಿಸಿ, ಸಂತತಿ ಎಣಿಸಿ, ಅವು 3 : 1 (ಅಥವಾ ಪರೀಕ್ಷಾ ಸಂಕರಣದಲ್ಲಿ 1 : 1) ಕ್ಕೆ ಹೊಂದುತ್ತವೆಯೇ ಎಂದು ಪರೀಕ್ಷಿಸಿ.'),
        aim=W('To verify the law of segregation with a monohybrid cross and a test cross.', 'एकसंकर संकरण और परीक्षण संकरण से पृथक्करण के नियम का सत्यापन करना।', 'ಏಕಸಂಕರ ಸಂಕರಣ ಮತ್ತು ಪರೀಕ್ಷಾ ಸಂಕರಣದಿಂದ ಪ್ರತ್ಯೇಕತೆಯ ನಿಯಮ ಪರಿಶೀಲಿಸುವುದು.'),
        principle=W('Each plant has two alleles of a gene and passes one, chosen at random, to each gamete (segregation). Crossing two hybrids Aa × Aa gives AA : Aa : aa = 1 : 2 : 1, that is 3 tall : 1 dwarf. Crossing a hybrid with the recessive parent (test cross) gives 1 : 1. Real counts scatter around the ratio; χ² tells whether the scatter is just chance.', 'हर पौधे में जीन के दो युग्मविकल्पी होते हैं और वह हर युग्मक को यादृच्छिक रूप से एक देता है (पृथक्करण)। दो संकरों Aa × Aa से AA : Aa : aa = 1 : 2 : 1, अर्थात 3 लंबे : 1 बौना। संकर का अप्रभावी जनक से संकरण (परीक्षण संकरण) 1 : 1 देता है। वास्तविक गिनतियाँ अनुपात के आसपास बिखरती हैं; χ² बताता है कि बिखराव केवल संयोग है या नहीं।', 'ಪ್ರತಿ ಗಿಡದಲ್ಲಿ ಜೀನ್‌ನ ಎರಡು ಅಲೀಲ್‌ಗಳಿವೆ; ಪ್ರತಿ ಯುಗ್ಮಕಕ್ಕೆ ಯಾದೃಚ್ಛಿಕವಾಗಿ ಒಂದನ್ನು ನೀಡುತ್ತದೆ (ಪ್ರತ್ಯೇಕತೆ). ಎರಡು ಸಂಕರಗಳು Aa × Aa ನೀಡುವುದು AA : Aa : aa = 1 : 2 : 1, ಅಂದರೆ 3 ಎತ್ತರ : 1 ಕುಬ್ಜ. ಸಂಕರವನ್ನು ಅಪ್ರಬಲ ಪೋಷಕದೊಂದಿಗೆ ಸಂಕರಿಸಿದರೆ (ಪರೀಕ್ಷಾ ಸಂಕರಣ) 1 : 1. ನಿಜವಾದ ಎಣಿಕೆಗಳು ಅನುಪಾತದ ಸುತ್ತ ಚದುರುತ್ತವೆ; ಚದುರುವಿಕೆ ಆಕಸ್ಮಿಕವೇ ಎಂದು χ² ಹೇಳುತ್ತದೆ.'),
        apparatus=[W('Pure-line tall and dwarf pea plants', 'शुद्ध वंश के लंबे और बौने मटर के पौधे', 'ಶುದ್ಧ ವಂಶದ ಎತ್ತರ ಮತ್ತು ಕುಬ್ಜ ಬಟಾಣಿ ಗಿಡಗಳು'), W('Brush, bags and labels for hand pollination', 'हस्त परागण के लिए ब्रश, थैलियाँ और लेबल', 'ಕೈ ಪರಾಗಸ್ಪರ್ಶಕ್ಕೆ ಬ್ರಷ್, ಚೀಲಗಳು ಮತ್ತು ಲೇಬಲ್‌ಗಳು'), W('Chi-square table', 'काई-वर्ग सारणी', 'ಕೈ-ವರ್ಗ ಕೋಷ್ಟಕ')],
        steps=[W('Draw the Punnett square for the cross and write the expected ratio.', 'संकरण का पनेट वर्ग बनाएँ और अपेक्षित अनुपात लिखें।', 'ಸಂಕರಣದ ಪನೆಟ್ ಚೌಕ ರಚಿಸಿ ನಿರೀಕ್ಷಿತ ಅನುಪಾತ ಬರೆಯಿರಿ.'),
               W('Count the offspring of each kind; record a small family (16) and a large one (400).', 'हर प्रकार की संतति गिनें; एक छोटा परिवार (16) और एक बड़ा (400) दर्ज करें।', 'ಪ್ರತಿ ಬಗೆಯ ಸಂತತಿಯನ್ನು ಎಣಿಸಿ; ಸಣ್ಣ ಕುಟುಂಬ (16) ಮತ್ತು ದೊಡ್ಡದು (400) ದಾಖಲಿಸಿ.'),
               CHI,
               W('Repeat with the test cross Aa × aa and with AA × aa.', 'परीक्षण संकरण Aa × aa और AA × aa के साथ दोहराएँ।', 'ಪರೀಕ್ಷಾ ಸಂಕರಣ Aa × aa ಮತ್ತು AA × aa ಯೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ.')],
        precautions=[W('Remove the anthers of the female parent before they shed pollen (emasculation) and bag the flower.', 'मादा जनक के परागकोश परागण से पहले हटाएँ (विपुंसन) और फूल को थैली से ढकें।', 'ಹೆಣ್ಣು ಪೋಷಕದ ಪರಾಗಕೋಶಗಳನ್ನು ಪರಾಗ ಉದುರಿಸುವ ಮೊದಲು ತೆಗೆದು (ಪುಂಸತ್ವಹರಣ) ಹೂವನ್ನು ಚೀಲದಲ್ಲಿ ಮುಚ್ಚಿ.'), W('Count every plant, not just a convenient sample.', 'हर पौधा गिनें, केवल सुविधाजनक नमूना नहीं।', 'ಅನುಕೂಲದ ಮಾದರಿ ಮಾತ್ರವಲ್ಲ, ಪ್ರತಿ ಗಿಡವನ್ನೂ ಎಣಿಸಿ.')],
        conclusion=W('The F₂ of a monohybrid cross fits 3 : 1 and the test cross fits 1 : 1, as the law of segregation predicts; larger counts lie closer to the ratio.', 'एकसंकर संकरण की F₂ पीढ़ी 3 : 1 और परीक्षण संकरण 1 : 1 से मेल खाती है, जैसा पृथक्करण का नियम बताता है; बड़ी गिनतियाँ अनुपात के अधिक निकट होती हैं।', 'ಏಕಸಂಕರ ಸಂಕರಣದ F₂ 3 : 1 ಕ್ಕೆ, ಪರೀಕ್ಷಾ ಸಂಕರಣ 1 : 1 ಕ್ಕೆ ಹೊಂದುತ್ತದೆ, ಪ್ರತ್ಯೇಕತೆಯ ನಿಯಮ ಹೇಳುವಂತೆ; ದೊಡ್ಡ ಎಣಿಕೆಗಳು ಅನುಪಾತಕ್ಕೆ ಹೆಚ್ಚು ಹತ್ತಿರ.'),
        viva=[Q(W('What is the genotypic ratio of the F₂?', 'F₂ का जीनप्ररूपी अनुपात क्या है?', 'F₂ ನ ಜೀನ್‌ರೂಪ ಅನುಪಾತ ಏನು?'), W('1 AA : 2 Aa : 1 aa.', '1 AA : 2 Aa : 1 aa (एक, दो, एक)।', '1 AA : 2 Aa : 1 aa (ಒಂದು, ಎರಡು, ಒಂದು).')),
              Q(W('Why is a test cross useful?', 'परीक्षण संकरण क्यों उपयोगी है?', 'ಪರೀಕ್ಷಾ ಸಂಕರಣ ಏಕೆ ಉಪಯುಕ್ತ?'), W('It shows whether a dominant-looking plant is AA (all dominant offspring) or Aa (half recessive).', 'यह दिखाता है कि प्रभावी दिखने वाला पौधा AA है (सब प्रभावी संतति) या Aa (आधी अप्रभावी)।', 'ಪ್ರಬಲವಾಗಿ ಕಾಣುವ ಗಿಡ AA (ಎಲ್ಲ ಪ್ರಬಲ ಸಂತತಿ) ಅಥವಾ Aa (ಅರ್ಧ ಅಪ್ರಬಲ) ಎಂದು ತೋರಿಸುತ್ತದೆ.')),
              Q(W('Why did Mendel choose peas?', 'मेंडल ने मटर क्यों चुना?', 'ಮೆಂಡಲ್ ಬಟಾಣಿಯನ್ನೇ ಏಕೆ ಆರಿಸಿದರು?'), W('Clear contrasting traits, self-pollination, many seeds and a short life cycle.', 'स्पष्ट विपरीत लक्षण, स्वपरागण, अधिक बीज और छोटा जीवन चक्र।', 'ಸ್ಪಷ್ಟ ವಿರುದ್ಧ ಲಕ್ಷಣಗಳು, ಸ್ವಪರಾಗಸ್ಪರ್ಶ, ಹಲವು ಬೀಜಗಳು ಮತ್ತು ಚಿಕ್ಕ ಜೀವನಚಕ್ರ.'))])

    lab(id='dihybrid-cross', bench='cross', setup={'set': 'di', 'cross': 'AaBb×AaBb'}, levels=[12, 'ug'], curricula=['cbse', 'ncert', 'ka-puc', 'ug-biology'], **bio,
        keywords=['dihybrid cross', 'independent assortment', 'mendel', '9:3:3:1', 'chi square', 'genetics'],
        title=W("Mendel's dihybrid cross", 'मेंडल का द्विसंकर संकरण', 'ಮೆಂಡಲ್‌ನ ದ್ವಿಸಂಕರ ಸಂಕರಣ'),
        summary=W('Follow seed shape and colour together, count the F₂ and test the 9 : 3 : 3 : 1 ratio.', 'बीज का आकार और रंग साथ-साथ देखें, F₂ गिनें और 9 : 3 : 3 : 1 अनुपात की जाँच करें।', 'ಬೀಜದ ಆಕಾರ ಮತ್ತು ಬಣ್ಣವನ್ನು ಒಟ್ಟಿಗೆ ಗಮನಿಸಿ, F₂ ಎಣಿಸಿ 9 : 3 : 3 : 1 ಅನುಪಾತ ಪರೀಕ್ಷಿಸಿ.'),
        aim=W('To verify the law of independent assortment with a dihybrid cross.', 'द्विसंकर संकरण से स्वतंत्र अपव्यूहन के नियम का सत्यापन करना।', 'ದ್ವಿಸಂಕರ ಸಂಕರಣದಿಂದ ಸ್ವತಂತ್ರ ವಿಂಗಡಣೆಯ ನಿಯಮ ಪರಿಶೀಲಿಸುವುದು.'),
        principle=W('When two genes are on different chromosomes their alleles go into gametes independently, so an AaBb plant makes AB, Ab, aB and ab gametes equally. Selfing it gives 9 round yellow : 3 round green : 3 wrinkled yellow : 1 wrinkled green. χ² with 3 degrees of freedom (critical 7.815) tests the fit.', 'जब दो जीन भिन्न गुणसूत्रों पर हों तो उनके युग्मविकल्पी स्वतंत्र रूप से युग्मकों में जाते हैं, अतः AaBb पौधा AB, Ab, aB और ab युग्मक बराबर बनाता है। इसका स्वपरागण 9 गोल पीले : 3 गोल हरे : 3 झुर्रीदार पीले : 1 झुर्रीदार हरा देता है। 3 स्वातंत्र्य कोटि (क्रांतिक 7.815) वाला χ² मेल की जाँच करता है।', 'ಎರಡು ಜೀನ್‌ಗಳು ಬೇರೆ ವರ್ಣತಂತುಗಳಲ್ಲಿದ್ದರೆ ಅವುಗಳ ಅಲೀಲ್‌ಗಳು ಸ್ವತಂತ್ರವಾಗಿ ಯುಗ್ಮಕಗಳಿಗೆ ಹೋಗುತ್ತವೆ; ಆದ್ದರಿಂದ AaBb ಗಿಡ AB, Ab, aB, ab ಯುಗ್ಮಕಗಳನ್ನು ಸಮವಾಗಿ ತಯಾರಿಸುತ್ತದೆ. ಸ್ವಸಂಕರಣ 9 ದುಂಡು ಹಳದಿ : 3 ದುಂಡು ಹಸಿರು : 3 ಸುಕ್ಕು ಹಳದಿ : 1 ಸುಕ್ಕು ಹಸಿರು ನೀಡುತ್ತದೆ. 3 ಸ್ವಾತಂತ್ರ್ಯ ಮಟ್ಟದ χ² (ನಿರ್ಣಾಯಕ 7.815) ಹೊಂದಿಕೆ ಪರೀಕ್ಷಿಸುತ್ತದೆ.'),
        apparatus=[W('Pure-line round yellow and wrinkled green pea plants', 'शुद्ध वंश के गोल पीले और झुर्रीदार हरे मटर के पौधे', 'ಶುದ್ಧ ವಂಶದ ದುಂಡು ಹಳದಿ ಮತ್ತು ಸುಕ್ಕು ಹಸಿರು ಬಟಾಣಿ ಗಿಡಗಳು'), W('Seed trays and counters', 'बीज ट्रे और गणक', 'ಬೀಜದ ತಟ್ಟೆಗಳು ಮತ್ತು ಎಣಿಕೆಗಾರರು'), W('Chi-square table', 'काई-वर्ग सारणी', 'ಕೈ-ವರ್ಗ ಕೋಷ್ಟಕ')],
        steps=[W('Write the four gametes of AaBb and fill in the 16-box Punnett square.', 'AaBb के चार युग्मक लिखें और 16 खानों वाला पनेट वर्ग भरें।', 'AaBb ನ ನಾಲ್ಕು ಯುಗ್ಮಕಗಳನ್ನು ಬರೆದು 16 ಚೌಕಗಳ ಪನೆಟ್ ಚೌಕ ತುಂಬಿ.'),
               W('Sort and count the F₂ seeds into the four classes.', 'F₂ बीजों को चार वर्गों में छाँटकर गिनें।', 'F₂ ಬೀಜಗಳನ್ನು ನಾಲ್ಕು ವರ್ಗಗಳಾಗಿ ವಿಂಗಡಿಸಿ ಎಣಿಸಿ.'),
               CHI,
               W('Repeat with the test cross AaBb × aabb (expected 1 : 1 : 1 : 1).', 'परीक्षण संकरण AaBb × aabb (अपेक्षित 1 : 1 : 1 : 1) के साथ दोहराएँ।', 'ಪರೀಕ್ಷಾ ಸಂಕರಣ AaBb × aabb (ನಿರೀಕ್ಷಿತ 1 : 1 : 1 : 1) ಯೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ.')],
        precautions=[W('Score each seed for both traits before putting it in a class.', 'हर बीज को वर्ग में डालने से पहले दोनों लक्षणों के लिए जाँचें।', 'ಪ್ರತಿ ಬೀಜವನ್ನು ವರ್ಗಕ್ಕೆ ಹಾಕುವ ಮೊದಲು ಎರಡೂ ಲಕ್ಷಣಗಳಿಗೆ ಪರೀಕ್ಷಿಸಿ.'), W('Use counts, never percentages, in the chi-square test.', 'काई-वर्ग परीक्षण में गिनतियाँ लें, प्रतिशत कभी नहीं।', 'ಕೈ-ವರ್ಗ ಪರೀಕ್ಷೆಯಲ್ಲಿ ಎಣಿಕೆಗಳನ್ನು ಬಳಸಿ, ಶೇಕಡಾ ಎಂದೂ ಬೇಡ.')],
        conclusion=W('The F₂ fits 9 : 3 : 3 : 1 and the test cross 1 : 1 : 1 : 1: the two genes assort independently.', 'F₂ पीढ़ी 9 : 3 : 3 : 1 और परीक्षण संकरण 1 : 1 : 1 : 1 से मेल खाता है: दोनों जीन स्वतंत्र रूप से अपव्यूहित होते हैं।', 'F₂ 9 : 3 : 3 : 1 ಕ್ಕೆ, ಪರೀಕ್ಷಾ ಸಂಕರಣ 1 : 1 : 1 : 1 ಕ್ಕೆ ಹೊಂದುತ್ತದೆ: ಎರಡು ಜೀನ್‌ಗಳು ಸ್ವತಂತ್ರವಾಗಿ ವಿಂಗಡಣೆಯಾಗುತ್ತವೆ.'),
        viva=[Q(W('When does independent assortment fail?', 'स्वतंत्र अपव्यूहन कब लागू नहीं होता?', 'ಸ್ವತಂತ್ರ ವಿಂಗಡಣೆ ಯಾವಾಗ ವಿಫಲ?'), W('When the genes are close together on the same chromosome (linkage).', 'जब जीन एक ही गुणसूत्र पर पास-पास हों (सहलग्नता)।', 'ಜೀನ್‌ಗಳು ಒಂದೇ ವರ್ಣತಂತುವಿನಲ್ಲಿ ಹತ್ತಿರವಿದ್ದಾಗ (ಸಹಲಗ್ನತೆ).')),
              Q(W('How many kinds of gametes does AaBb make?', 'AaBb कितने प्रकार के युग्मक बनाता है?', 'AaBb ಎಷ್ಟು ಬಗೆಯ ಯುಗ್ಮಕಗಳನ್ನು ತಯಾರಿಸುತ್ತದೆ?'), W('Four: AB, Ab, aB and ab.', 'चार: AB, Ab, aB और ab।', 'ನಾಲ್ಕು: AB, Ab, aB ಮತ್ತು ab.')),
              Q(W('How many genotypes are in the F₂?', 'F₂ में कितने जीनप्ररूप हैं?', 'F₂ ನಲ್ಲಿ ಎಷ್ಟು ಜೀನ್‌ರೂಪಗಳು?'), W('Nine.', 'नौ।', 'ಒಂಬತ್ತು.'))])

    lab(id='hardy-weinberg', bench='hardy-weinberg', levels=[12, 'ug', 'pg'], curricula=['cbse', 'ncert', 'ug-biology'], **bio,
        keywords=['hardy weinberg', 'population genetics', 'allele frequency', 'evolution', 'chi square', 'inbreeding', 'gene pool'],
        title=W('Hardy–Weinberg equilibrium', 'हार्डी–वाइनबर्ग साम्य', 'ಹಾರ್ಡಿ–ವೈನ್‌ಬರ್ಗ್ ಸಮತೋಲನ'),
        summary=W('Count genotypes in samples from three populations, find the allele frequencies and test for equilibrium.', 'तीन समष्टियों के नमूनों में जीनप्ररूप गिनें, युग्मविकल्पी आवृत्तियाँ ज्ञात करें और साम्य की जाँच करें।', 'ಮೂರು ಜನಸಂಖ್ಯೆಗಳ ಮಾದರಿಗಳಲ್ಲಿ ಜೀನ್‌ರೂಪಗಳನ್ನು ಎಣಿಸಿ, ಅಲೀಲ್ ಆವರ್ತನಗಳನ್ನು ಕಂಡುಹಿಡಿದು ಸಮತೋಲನ ಪರೀಕ್ಷಿಸಿ.'),
        aim=W('To find allele frequencies from genotype counts and test whether a population is in Hardy–Weinberg equilibrium.', 'जीनप्ररूप गिनतियों से युग्मविकल्पी आवृत्तियाँ ज्ञात करना और जाँचना कि समष्टि हार्डी–वाइनबर्ग साम्य में है या नहीं।', 'ಜೀನ್‌ರೂಪ ಎಣಿಕೆಗಳಿಂದ ಅಲೀಲ್ ಆವರ್ತನ ಕಂಡುಹಿಡಿದು ಜನಸಂಖ್ಯೆ ಹಾರ್ಡಿ–ವೈನ್‌ಬರ್ಗ್ ಸಮತೋಲನದಲ್ಲಿದೆಯೇ ಎಂದು ಪರೀಕ್ಷಿಸುವುದು.'),
        principle=W('With random mating and no selection, migration, mutation or drift, allele frequencies p and q stay constant and genotypes settle at p² : 2pq : q². p = (2·AA + Aa) ÷ 2N. A χ² test with one degree of freedom (critical 3.84) compares the counts with p², 2pq, q². Inbreeding, or pooling two different populations, gives too few heterozygotes.', 'यादृच्छिक संगम और चयन, प्रवास, उत्परिवर्तन या अपवाह के न होने पर युग्मविकल्पी आवृत्तियाँ p और q स्थिर रहती हैं और जीनप्ररूप p² : 2pq : q² पर स्थिर होते हैं। p = (2·AA + Aa) ÷ 2N। एक स्वातंत्र्य कोटि (क्रांतिक 3.84) वाला χ² परीक्षण गिनतियों की p², 2pq, q² से तुलना करता है। अंतःप्रजनन, या दो भिन्न समष्टियों को मिलाकर गिनना, बहुत कम विषमयुग्मज देता है।', 'ಯಾದೃಚ್ಛಿಕ ಸಂಗಮ ಮತ್ತು ಆಯ್ಕೆ, ವಲಸೆ, ಉತ್ಪರಿವರ್ತನೆ ಅಥವಾ ಅಲೆತ ಇಲ್ಲದಿದ್ದರೆ ಅಲೀಲ್ ಆವರ್ತನಗಳು p ಮತ್ತು q ಸ್ಥಿರ; ಜೀನ್‌ರೂಪಗಳು p² : 2pq : q² ನಲ್ಲಿ ನೆಲೆಸುತ್ತವೆ. p = (2·AA + Aa) ÷ 2N. ಒಂದು ಸ್ವಾತಂತ್ರ್ಯ ಮಟ್ಟದ χ² (ನಿರ್ಣಾಯಕ 3.84) ಎಣಿಕೆಗಳನ್ನು p², 2pq, q² ಗೆ ಹೋಲಿಸುತ್ತದೆ. ಅಂತಃಸಂಕರಣ ಅಥವಾ ಎರಡು ಬೇರೆ ಜನಸಂಖ್ಯೆಗಳನ್ನು ಒಟ್ಟಿಗೆ ಎಣಿಸುವುದು ತುಂಬ ಕಡಿಮೆ ವಿಷಮಯುಗ್ಮಜಗಳನ್ನು ನೀಡುತ್ತದೆ.'),
        apparatus=[W('Genotype data from population samples (or coloured beads)', 'समष्टि नमूनों के जीनप्ररूप आँकड़े (या रंगीन मनके)', 'ಜನಸಂಖ್ಯಾ ಮಾದರಿಗಳ ಜೀನ್‌ರೂಪ ದತ್ತಾಂಶ (ಅಥವಾ ಬಣ್ಣದ ಮಣಿಗಳು)'), W('Calculator', 'कैलकुलेटर', 'ಕ್ಯಾಲ್ಕುಲೇಟರ್'), W('Chi-square table', 'काई-वर्ग सारणी', 'ಕೈ-ವರ್ಗ ಕೋಷ್ಟಕ')],
        steps=[W('Count AA, Aa and aa in a sample from the first population.', 'पहली समष्टि के नमूने में AA, Aa और aa गिनें।', 'ಮೊದಲ ಜನಸಂಖ್ಯೆಯ ಮಾದರಿಯಲ್ಲಿ AA, Aa ಮತ್ತು aa ಎಣಿಸಿ.'),
               W('Work out p and q, and the expected counts p²N, 2pqN and q²N.', 'p और q, तथा अपेक्षित गिनतियाँ p²N, 2pqN और q²N निकालें।', 'p ಮತ್ತು q, ಹಾಗೂ ನಿರೀಕ್ಷಿತ ಎಣಿಕೆಗಳು p²N, 2pqN ಮತ್ತು q²N ಲೆಕ್ಕಿಸಿ.'),
               W('Find χ² and compare it with 3.84.', 'χ² ज्ञात करें और 3.84 से तुलना करें।', 'χ² ಕಂಡುಹಿಡಿದು 3.84 ರೊಂದಿಗೆ ಹೋಲಿಸಿ.'),
               W('Take several samples from each population and decide which are in equilibrium, and why the others are not.', 'हर समष्टि के कई नमूने लें और तय करें कि कौन साम्य में हैं, और अन्य क्यों नहीं।', 'ಪ್ರತಿ ಜನಸಂಖ್ಯೆಯಿಂದ ಹಲವು ಮಾದರಿಗಳನ್ನು ತೆಗೆದು ಯಾವುವು ಸಮತೋಲನದಲ್ಲಿವೆ, ಇತರವು ಏಕೆ ಇಲ್ಲ ಎಂದು ನಿರ್ಧರಿಸಿ.')],
        precautions=[W('Take samples at random from the whole population.', 'पूरी समष्टि से यादृच्छिक रूप से नमूने लें।', 'ಇಡೀ ಜನಸಂಖ್ಯೆಯಿಂದ ಯಾದೃಚ್ಛಿಕವಾಗಿ ಮಾದರಿ ತೆಗೆದುಕೊಳ್ಳಿ.'), W('Remember one sample in twenty fails the test by chance at the 5 % level.', 'याद रखें, 5 % स्तर पर बीस में एक नमूना संयोग से परीक्षण में विफल होता है।', '5 % ಮಟ್ಟದಲ್ಲಿ ಇಪ್ಪತ್ತರಲ್ಲಿ ಒಂದು ಮಾದರಿ ಆಕಸ್ಮಿಕವಾಗಿ ವಿಫಲವಾಗುತ್ತದೆ ಎಂಬುದು ನೆನಪಿರಲಿ.')],
        conclusion=W('The randomly mating town is in equilibrium; the inbred island and the pooled villages have too few heterozygotes and are not.', 'यादृच्छिक संगम वाला नगर साम्य में है; अंतःप्रजनित द्वीप और मिलाए गए गाँवों में बहुत कम विषमयुग्मज हैं और वे साम्य में नहीं हैं।', 'ಯಾದೃಚ್ಛಿಕ ಸಂಗಮದ ಪಟ್ಟಣ ಸಮತೋಲನದಲ್ಲಿದೆ; ಅಂತಃಸಂಕರಣದ ದ್ವೀಪ ಮತ್ತು ಒಟ್ಟುಗೂಡಿಸಿದ ಹಳ್ಳಿಗಳಲ್ಲಿ ತುಂಬ ಕಡಿಮೆ ವಿಷಮಯುಗ್ಮಜಗಳಿದ್ದು ಅವು ಸಮತೋಲನದಲ್ಲಿಲ್ಲ.'),
        viva=[Q(W('If q² = 0.09, what are q and p?', 'यदि q² = 0.09 है, तो q और p क्या हैं?', 'q² = 0.09 ಆದರೆ q ಮತ್ತು p ಎಷ್ಟು?'), W('q = 0.3 and p = 0.7.', 'q = 0.3 और p = 0.7।', 'q = 0.3 ಮತ್ತು p = 0.7.')),
              Q(W('Name the five forces that disturb the equilibrium.', 'साम्य भंग करने वाले पाँच बल बताइए।', 'ಸಮತೋಲನವನ್ನು ಕದಡುವ ಐದು ಬಲಗಳನ್ನು ಹೆಸರಿಸಿ.'), W('Mutation, migration (gene flow), genetic drift, non-random mating and natural selection.', 'उत्परिवर्तन, प्रवास (जीन प्रवाह), आनुवंशिक अपवाह, अयादृच्छिक संगम और प्राकृतिक चयन।', 'ಉತ್ಪರಿವರ್ತನೆ, ವಲಸೆ (ಜೀನ್ ಹರಿವು), ಆನುವಂಶಿಕ ಅಲೆತ, ಯಾದೃಚ್ಛಿಕವಲ್ಲದ ಸಂಗಮ ಮತ್ತು ನೈಸರ್ಗಿಕ ಆಯ್ಕೆ.')),
              Q(W('Why does χ² here have only one degree of freedom?', 'यहाँ χ² की केवल एक स्वातंत्र्य कोटि क्यों है?', 'ಇಲ್ಲಿ χ² ಗೆ ಒಂದೇ ಸ್ವಾತಂತ್ರ್ಯ ಮಟ್ಟ ಏಕೆ?'), W('Three classes, minus one for the total and one more because p was estimated from the data.', 'तीन वर्ग, एक कुल के लिए घटाएँ और एक और क्योंकि p आँकड़ों से अनुमानित हुआ।', 'ಮೂರು ವರ್ಗಗಳು; ಒಟ್ಟಿಗೆ ಒಂದು ಕಳೆಯಿರಿ, p ದತ್ತಾಂಶದಿಂದ ಅಂದಾಜಿಸಿದ್ದರಿಂದ ಇನ್ನೊಂದು.'))])

    lab(id='genetic-drift', bench='drift', levels=['ug', 'pg'], mode='explore', **ug,
        keywords=['genetic drift', 'population genetics', 'wright fisher', 'allele fixation', 'natural selection', 'evolution', 'population size'],
        title=W('Genetic drift and population size', 'आनुवंशिक अपवाह और समष्टि आकार', 'ಆನುವಂಶಿಕ ಅಲೆತ ಮತ್ತು ಜನಸಂಖ್ಯಾ ಗಾತ್ರ'),
        summary=W('Watch an allele’s frequency wander by chance over 100 generations in small and large populations, with and without selection.', 'छोटी और बड़ी समष्टियों में, चयन सहित और रहित, 100 पीढ़ियों में एक युग्मविकल्पी की आवृत्ति को संयोग से भटकते देखें।', 'ಸಣ್ಣ ಮತ್ತು ದೊಡ್ಡ ಜನಸಂಖ್ಯೆಗಳಲ್ಲಿ, ಆಯ್ಕೆ ಸಹಿತ ಮತ್ತು ರಹಿತ, 100 ಪೀಳಿಗೆಗಳಲ್ಲಿ ಒಂದು ಅಲೀಲ್‌ನ ಆವರ್ತನ ಆಕಸ್ಮಿಕವಾಗಿ ಅಲೆಯುವುದನ್ನು ನೋಡಿ.'),
        aim=W('To study how population size affects genetic drift, and how selection overrides it.', 'समष्टि आकार आनुवंशिक अपवाह को कैसे प्रभावित करता है और चयन उस पर कैसे भारी पड़ता है, इसका अध्ययन करना।', 'ಜನಸಂಖ್ಯಾ ಗಾತ್ರ ಆನುವಂಶಿಕ ಅಲೆತವನ್ನು ಹೇಗೆ ಪ್ರಭಾವಿಸುತ್ತದೆ ಮತ್ತು ಆಯ್ಕೆ ಅದನ್ನು ಹೇಗೆ ಮೀರಿಸುತ್ತದೆ ಎಂದು ಅಧ್ಯಯನ ಮಾಡುವುदು.'),
        principle=W('Each generation is a random sample of 2N gene copies from the last (the Wright–Fisher model). The change in p from one generation to the next has variance pq ÷ 2N, so small populations drift fast and often lose an allele altogether, while large ones barely move. Selection against aa pushes p up steadily whatever the size.', 'हर पीढ़ी पिछली पीढ़ी से 2N जीन प्रतियों का यादृच्छिक नमूना है (राइट–फ़िशर मॉडल)। एक पीढ़ी से अगली में p के परिवर्तन का प्रसरण pq ÷ 2N है, अतः छोटी समष्टियाँ तेज़ी से भटकती हैं और प्रायः एक युग्मविकल्पी पूरी तरह खो देती हैं, जबकि बड़ी मुश्किल से हिलती हैं। aa के विरुद्ध चयन आकार चाहे जो हो, p को लगातार ऊपर धकेलता है।', 'ಪ್ರತಿ ಪೀಳಿಗೆ ಹಿಂದಿನದರಿಂದ 2N ಜೀನ್ ಪ್ರತಿಗಳ ಯಾದೃಚ್ಛಿಕ ಮಾದರಿ (ರೈಟ್–ಫಿಶರ್ ಮಾದರಿ). ಒಂದು ಪೀಳಿಗೆಯಿಂದ ಮುಂದಿನದಕ್ಕೆ p ಬದಲಾವಣೆಯ ವ್ಯತ್ಯಯ pq ÷ 2N; ಆದ್ದರಿಂದ ಸಣ್ಣ ಜನಸಂಖ್ಯೆಗಳು ವೇಗವಾಗಿ ಅಲೆಯುತ್ತವೆ ಮತ್ತು ಆಗಾಗ ಒಂದು ಅಲೀಲ್ ಸಂಪೂರ್ಣ ಕಳೆದುಕೊಳ್ಳುತ್ತವೆ; ದೊಡ್ಡವು ಅಷ್ಟೇನೂ ಚಲಿಸುವುದಿಲ್ಲ. aa ವಿರುದ್ಧ ಆಯ್ಕೆ ಗಾತ್ರ ಏನೇ ಇರಲಿ p ಅನ್ನು ಸ್ಥಿರವಾಗಿ ಮೇಲೆ ತಳ್ಳುತ್ತದೆ.'),
        apparatus=[W('Simulated populations (or a bag of 2N beads in two colours)', 'अनुकारित समष्टियाँ (या दो रंगों के 2N मनकों की थैली)', 'ಅನುಕರಿಸಿದ ಜನಸಂಖ್ಯೆಗಳು (ಅಥವಾ ಎರಡು ಬಣ್ಣಗಳ 2N ಮಣಿಗಳ ಚೀಲ)'), W('Graph paper', 'ग्राफ़ पेपर', 'ಗ್ರಾಫ್ ಕಾಗದ'), W('Calculator', 'कैलकुलेटर', 'ಕ್ಯಾಲ್ಕುಲೇಟರ್')],
        steps=[W('Start with p = 0.5 and a population of 20; step through the generations and record p every 10.', 'p = 0.5 और 20 की समष्टि से शुरू करें; पीढ़ियाँ आगे बढ़ाएँ और हर 10 पर p दर्ज करें।', 'p = 0.5 ಮತ್ತು 20 ರ ಜನಸಂಖ್ಯೆಯಿಂದ ಆರಂಭಿಸಿ; ಪೀಳಿಗೆಗಳನ್ನು ಮುಂದುವರಿಸಿ ಪ್ರತಿ 10 ಕ್ಕೆ p ದಾಖಲಿಸಿ.'),
               W('Repeat with other trials, then with populations of 100 and 1000.', 'अन्य प्रयासों के साथ दोहराएँ, फिर 100 और 1000 की समष्टियों के साथ।', 'ಬೇರೆ ಪ್ರಯತ್ನಗಳೊಂದಿಗೆ, ನಂತರ 100 ಮತ್ತು 1000 ರ ಜನಸಂಖ್ಯೆಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Compare how far p has moved after 50 generations, and how many trials lost an allele.', 'तुलना करें कि 50 पीढ़ियों बाद p कितना हटा, और कितने प्रयासों में एक युग्मविकल्पी खो गया।', '50 ಪೀಳಿಗೆಗಳ ನಂತರ p ಎಷ್ಟು ಸರಿದಿದೆ, ಎಷ್ಟು ಪ್ರಯತ್ನಗಳಲ್ಲಿ ಒಂದು ಅಲೀಲ್ ಕಳೆದುಹೋಯಿತು ಎಂದು ಹೋಲಿಸಿ.'),
               W('Add selection against aa and see how it changes the paths.', 'aa के विरुद्ध चयन जोड़ें और देखें कि यह पथों को कैसे बदलता है।', 'aa ವಿರುದ್ಧ ಆಯ್ಕೆ ಸೇರಿಸಿ ಅದು ಮಾರ್ಗಗಳನ್ನು ಹೇಗೆ ಬದಲಿಸುತ್ತದೆ ಎಂದು ನೋಡಿ.')],
        precautions=[W('Compare many trials, not one: drift is random.', 'एक नहीं, कई प्रयासों की तुलना करें: अपवाह यादृच्छिक है।', 'ಒಂದಲ್ಲ, ಹಲವು ಪ್ರಯತ್ನಗಳನ್ನು ಹೋಲಿಸಿ: ಅಲೆತ ಯಾದೃಚ್ಛಿಕ.'), W('Keep the starting frequency the same when comparing sizes.', 'आकारों की तुलना करते समय प्रारंभिक आवृत्ति समान रखें।', 'ಗಾತ್ರಗಳನ್ನು ಹೋಲಿಸುವಾಗ ಆರಂಭಿಕ ಆವರ್ತನ ಒಂದೇ ಇಡಿ.')],
        conclusion=W('Drift is strong in small populations, which often fix or lose an allele within a few dozen generations, and weak in large ones; selection gives a steady, direction-giving change.', 'छोटी समष्टियों में अपवाह प्रबल है, जो प्रायः कुछ दर्जन पीढ़ियों में एक युग्मविकल्पी को स्थिर कर देती हैं या खो देती हैं, और बड़ी में दुर्बल; चयन एक स्थिर, दिशा देने वाला परिवर्तन लाता है।', 'ಸಣ್ಣ ಜನಸಂಖ್ಯೆಗಳಲ್ಲಿ ಅಲೆತ ಪ್ರಬಲ; ಅವು ಕೆಲವು ಡಜನ್ ಪೀಳಿಗೆಗಳಲ್ಲಿ ಒಂದು ಅಲೀಲ್ ಅನ್ನು ಸ್ಥಿರಗೊಳಿಸುತ್ತವೆ ಅಥವಾ ಕಳೆದುಕೊಳ್ಳುತ್ತವೆ; ದೊಡ್ಡವುಗಳಲ್ಲಿ ದುರ್ಬಲ; ಆಯ್ಕೆ ಸ್ಥಿರ, ದಿಕ್ಕು ನೀಡುವ ಬದಲಾವಣೆ ತರುತ್ತದೆ.'),
        viva=[Q(W('What is the founder effect?', 'संस्थापक प्रभाव क्या है?', 'ಸ್ಥಾಪಕ ಪರಿಣಾಮ ಎಂದರೇನು?'), W('Drift when a few individuals start a new population, carrying only part of the gene pool.', 'अपवाह जब कुछ व्यष्टि नई समष्टि शुरू करते हैं, जीन कोश का केवल एक भाग लेकर।', 'ಕೆಲವು ವ್ಯಕ್ತಿಗಳು ಜೀನ್ ಸಂಗ್ರಹದ ಒಂದು ಭಾಗವನ್ನು ಮಾತ್ರ ಹೊತ್ತು ಹೊಸ ಜನಸಂಖ್ಯೆ ಆರಂಭಿಸಿದಾಗಿನ ಅಲೆತ.')),
              Q(W('What is a bottleneck?', 'अड़चन (बॉटलनेक) क्या है?', 'ಅಡಚಣೆ (ಬಾಟಲ್‌ನೆಕ್) ಎಂದರೇನು?'), W('A sudden fall in population size that lets drift change allele frequencies sharply.', 'समष्टि आकार में अचानक गिरावट जिससे अपवाह युग्मविकल्पी आवृत्तियों को तेज़ी से बदल देता है।', 'ಜನಸಂಖ್ಯಾ ಗಾತ್ರದಲ್ಲಿ ಹಠಾತ್ ಕುಸಿತ; ಇದರಿಂದ ಅಲೆತ ಅಲೀಲ್ ಆವರ್ತನಗಳನ್ನು ತೀವ್ರವಾಗಿ ಬದಲಿಸುತ್ತದೆ.')),
              Q(W('Once p reaches 1, can drift change it?', 'p के 1 हो जाने पर क्या अपवाह उसे बदल सकता है?', 'p 1 ತಲುಪಿದ ಮೇಲೆ ಅಲೆತ ಅದನ್ನು ಬದಲಿಸಬಹುದೇ?'), W('No; only mutation or migration can bring the lost allele back.', 'नहीं; केवल उत्परिवर्तन या प्रवास ही खोए युग्मविकल्पी को वापस ला सकते हैं।', 'ಇಲ್ಲ; ಉತ್ಪರಿವರ್ತನೆ ಅಥವಾ ವಲಸೆ ಮಾತ್ರ ಕಳೆದುಹೋದ ಅಲೀಲ್ ಅನ್ನು ಮರಳಿ ತರಬಲ್ಲವು.'))])

    lab(id='gel-electrophoresis', bench='gel', setup={'kit': 'plasmid'}, levels=['ug', 'pg'], **ug,
        keywords=['gel electrophoresis', 'agarose', 'dna', 'restriction digest', 'dna ladder', 'biotechnology', 'fragment size'],
        title=W('Agarose gel electrophoresis of DNA', 'DNA का एगारोज़ जेल वैद्युतकणसंचलन', 'DNA ಯ ಅಗರೋಸ್ ಜೆಲ್ ವಿದ್ಯುತ್ ಕಣಚಲನೆ'),
        summary=W('Run a ladder and plasmid digests, measure how far each band travels, and size the unknown fragments.', 'एक लैडर और प्लाज़्मिड पाचन चलाएँ, हर पट्टी की दूरी मापें और अज्ञात खंडों का आकार ज्ञात करें।', 'ಒಂದು ಲ್ಯಾಡರ್ ಮತ್ತು ಪ್ಲಾಸ್ಮಿಡ್ ಜೀರ್ಣಗಳನ್ನು ಓಡಿಸಿ, ಪ್ರತಿ ಪಟ್ಟಿ ಸಾಗಿದ ದೂರ ಅಳೆದು ಅಜ್ಞಾತ ತುಣುಕುಗಳ ಗಾತ್ರ ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To separate DNA fragments by agarose gel electrophoresis and estimate their sizes from a standard ladder.', 'एगारोज़ जेल वैद्युतकणसंचलन से DNA खंडों को अलग करना और मानक लैडर से उनके आकार का अनुमान लगाना।', 'ಅಗರೋಸ್ ಜೆಲ್ ವಿದ್ಯುತ್ ಕಣಚಲನೆಯಿಂದ DNA ತುಣುಕುಗಳನ್ನು ಬೇರ್ಪಡಿಸಿ ಪ್ರಮಾಣಿತ ಲ್ಯಾಡರ್‌ನಿಂದ ಅವುಗಳ ಗಾತ್ರ ಅಂದಾಜಿಸುವುದು.'),
        principle=W('DNA is negatively charged and moves towards the positive electrode. The gel acts as a sieve: small fragments travel further. Over the working range, distance falls in a straight line with log(size), so a ladder of known sizes gives a calibration line from which unknown sizes are read. Denser gels separate small fragments better.', 'DNA ऋणावेशित है और धनात्मक इलेक्ट्रोड की ओर चलता है। जेल छलनी का काम करता है: छोटे खंड अधिक दूर जाते हैं। कार्य परास में दूरी log(आकार) के साथ सीधी रेखा में घटती है, अतः ज्ञात आकारों का लैडर अंशांकन रेखा देता है जिससे अज्ञात आकार पढ़े जाते हैं। सघन जेल छोटे खंडों को बेहतर अलग करते हैं।', 'DNA ಋಣಾವೇಶಿತ; ಧನ ವಿದ್ಯುದ್ವಾರದ ಕಡೆಗೆ ಸಾಗುತ್ತದೆ. ಜೆಲ್ ಜರಡಿಯಂತೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ: ಸಣ್ಣ ತುಣುಕುಗಳು ಹೆಚ್ಚು ದೂರ ಸಾಗುತ್ತವೆ. ಕಾರ್ಯ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ ದೂರ log(ಗಾತ್ರ) ದೊಂದಿಗೆ ನೇರ ರೇಖೆಯಲ್ಲಿ ಇಳಿಯುತ್ತದೆ; ಆದ್ದರಿಂದ ತಿಳಿದ ಗಾತ್ರಗಳ ಲ್ಯಾಡರ್ ಮಾಪನ ರೇಖೆ ನೀಡುತ್ತದೆ, ಅದರಿಂದ ಅಜ್ಞಾತ ಗಾತ್ರಗಳನ್ನು ಓದಬಹುದು. ದಟ್ಟ ಜೆಲ್‌ಗಳು ಸಣ್ಣ ತುಣುಕುಗಳನ್ನು ಉತ್ತಮವಾಗಿ ಬೇರ್ಪಡಿಸುತ್ತವೆ.'),
        apparatus=[W('Agarose, TAE buffer, casting tray and comb', 'एगारोज़, TAE बफ़र, ढलाई ट्रे और कंघी', 'ಅಗರೋಸ್, TAE ಬಫರ್, ಎರಕದ ತಟ್ಟೆ ಮತ್ತು ಬಾಚಣಿಗೆ'), W('Electrophoresis tank and power supply', 'वैद्युतकणसंचलन टंकी और विद्युत आपूर्ति', 'ವಿದ್ಯುತ್ ಕಣಚಲನೆ ತೊಟ್ಟಿ ಮತ್ತು ವಿದ್ಯುತ್ ಪೂರೈಕೆ'), W('DNA ladder, samples, loading dye, DNA stain and UV or blue-light viewer', 'DNA लैडर, नमूने, लोडिंग डाई, DNA अभिरंजक और UV या नीले प्रकाश का दर्शक', 'DNA ಲ್ಯಾಡರ್, ಮಾದರಿಗಳು, ಲೋಡಿಂಗ್ ಬಣ್ಣ, DNA ಬಣ್ಣಕಾರಕ ಮತ್ತು UV ಅಥವಾ ನೀಲಿ ಬೆಳಕಿನ ವೀಕ್ಷಕ')],
        steps=[W('Cast a 1 % agarose gel with the stain and place it in the tank, wells at the negative end.', 'अभिरंजक सहित 1 % एगारोज़ जेल ढालें और टंकी में रखें, गड्ढे ऋणात्मक सिरे पर।', 'ಬಣ್ಣಕಾರಕ ಸಹಿತ 1 % ಅಗರೋಸ್ ಜೆಲ್ ಎರಕಹೊಯ್ದು ತೊಟ್ಟಿಯಲ್ಲಿ ಇಡಿ, ಕುಳಿಗಳು ಋಣ ತುದಿಯಲ್ಲಿ.'),
               W('Load the ladder and the samples mixed with loading dye.', 'लैडर और लोडिंग डाई मिले नमूने भरें।', 'ಲ್ಯಾಡರ್ ಮತ್ತು ಲೋಡಿಂಗ್ ಬಣ್ಣ ಬೆರೆಸಿದ ಮಾದರಿಗಳನ್ನು ತುಂಬಿ.'),
               W('Run at 100 V for about 45 minutes, then view the bands.', 'लगभग 45 मिनट 100 V पर चलाएँ, फिर पट्टियाँ देखें।', 'ಸುಮಾರು 45 ನಿಮಿಷ 100 V ನಲ್ಲಿ ಓಡಿಸಿ, ನಂತರ ಪಟ್ಟಿಗಳನ್ನು ನೋಡಿ.'),
               W('Measure each band from its well; plot log₁₀(bp) against distance for the ladder and read off the unknowns.', 'हर पट्टी को उसके गड्ढे से मापें; लैडर के लिए दूरी के विरुद्ध log₁₀(bp) आलेखित करें और अज्ञात पढ़ें।', 'ಪ್ರತಿ ಪಟ್ಟಿಯನ್ನು ಅದರ ಕುಳಿಯಿಂದ ಅಳೆಯಿರಿ; ಲ್ಯಾಡರ್‌ಗೆ ದೂರದ ವಿರುದ್ಧ log₁₀(bp) ನಕ್ಷೆ ಮಾಡಿ ಅಜ್ಞಾತಗಳನ್ನು ಓದಿ.')],
        precautions=[GLOVES, W('Never look at UV light without a shield; DNA stains must be handled with care.', 'बिना आवरण के UV प्रकाश को कभी न देखें; DNA अभिरंजकों को सावधानी से सँभालें।', 'ರಕ್ಷಾಕವಚವಿಲ್ಲದೆ UV ಬೆಳಕನ್ನು ಎಂದೂ ನೋಡಬೇಡಿ; DNA ಬಣ್ಣಕಾರಕಗಳನ್ನು ಎಚ್ಚರದಿಂದ ನಿರ್ವಹಿಸಿ.'), W('Check the wells are at the negative (black) electrode before switching on.', 'चालू करने से पहले जाँचें कि गड्ढे ऋणात्मक (काले) इलेक्ट्रोड की ओर हैं।', 'ಆನ್ ಮಾಡುವ ಮೊದಲು ಕುಳಿಗಳು ಋಣ (ಕಪ್ಪು) ವಿದ್ಯುದ್ವಾರದ ಕಡೆ ಇವೆಯೇ ಪರೀಕ್ಷಿಸಿ.')],
        conclusion=W('log(size) falls linearly with distance; the double digest gives two fragments adding up to the plasmid size, and the unknown bands are sized to within a few per cent.', 'log(आकार) दूरी के साथ रैखिक रूप से घटता है; द्विपाचन से दो खंड मिलते हैं जिनका योग प्लाज़्मिड के आकार के बराबर है, और अज्ञात पट्टियों का आकार कुछ प्रतिशत के भीतर ज्ञात होता है।', 'log(ಗಾತ್ರ) ದೂರದೊಂದಿಗೆ ರೇಖೀಯವಾಗಿ ಇಳಿಯುತ್ತದೆ; ದ್ವಿಜೀರ್ಣ ಎರಡು ತುಣುಕುಗಳನ್ನು ನೀಡುತ್ತದೆ, ಅವುಗಳ ಮೊತ್ತ ಪ್ಲಾಸ್ಮಿಡ್ ಗಾತ್ರ; ಅಜ್ಞಾತ ಪಟ್ಟಿಗಳ ಗಾತ್ರ ಕೆಲವು ಶೇಕಡಾದೊಳಗೆ ತಿಳಿಯುತ್ತದೆ.'),
        viva=[Q(W('Why does DNA move towards the anode?', 'DNA ऐनोड की ओर क्यों जाता है?', 'DNA ಆನೋಡ್ ಕಡೆಗೆ ಏಕೆ ಸಾಗುತ್ತದೆ?'), W('Its phosphate backbone carries negative charges.', 'इसकी फ़ॉस्फ़ेट रीढ़ पर ऋण आवेश होते हैं।', 'ಅದರ ಫಾಸ್ಫೇಟ್ ಬೆನ್ನೆಲುಬಿನಲ್ಲಿ ಋಣ ಆವೇಶಗಳಿವೆ.')),
              Q(W('What does the loading dye do?', 'लोडिंग डाई क्या करता है?', 'ಲೋಡಿಂಗ್ ಬಣ್ಣ ಏನು ಮಾಡುತ್ತದೆ?'), W('It makes the sample dense enough to sink into the well and shows how far the run has gone.', 'यह नमूने को गड्ढे में डूबने लायक सघन बनाता है और दिखाता है कि रन कितना आगे बढ़ा।', 'ಮಾದರಿಯನ್ನು ಕುಳಿಯಲ್ಲಿ ಮುಳುಗುವಷ್ಟು ದಟ್ಟವಾಗಿಸುತ್ತದೆ, ಓಟ ಎಷ್ಟು ಸಾಗಿದೆ ಎಂದು ತೋರಿಸುತ್ತದೆ.')),
              Q(W('Why use a higher percentage gel for small fragments?', 'छोटे खंडों के लिए अधिक प्रतिशत जेल क्यों?', 'ಸಣ್ಣ ತುಣುಕುಗಳಿಗೆ ಹೆಚ್ಚಿನ ಶೇಕಡಾ ಜೆಲ್ ಏಕೆ?'), W('Its smaller pores spread small fragments further apart.', 'इसके छोटे छिद्र छोटे खंडों को अधिक दूर-दूर फैलाते हैं।', 'ಅದರ ಸಣ್ಣ ರಂಧ್ರಗಳು ಸಣ್ಣ ತುಣುಕುಗಳನ್ನು ಹೆಚ್ಚು ದೂರ ದೂರ ಹರಡುತ್ತವೆ.'))])

    lab(id='pcr-amplification', bench='pcr', levels=['ug', 'pg'], **ug,
        keywords=['pcr', 'polymerase chain reaction', 'qpcr', 'real time pcr', 'ct value', 'standard curve', 'amplification efficiency', 'biotechnology'],
        title=W('Real-time PCR: standard curve and efficiency', 'रियल-टाइम PCR: मानक वक्र और दक्षता', 'ರಿಯಲ್-ಟೈಮ್ PCR: ಪ್ರಮಾಣಿತ ವಕ್ರ ಮತ್ತು ದಕ್ಷತೆ'),
        summary=W('Amplify a ten-fold dilution series, record the threshold cycle of each, and find the efficiency and the copies in an unknown.', 'दस गुना तनुकरण शृंखला का प्रवर्धन करें, हर एक का थ्रेशोल्ड चक्र दर्ज करें, और दक्षता तथा अज्ञात में प्रतियाँ ज्ञात करें।', 'ಹತ್ತು ಪಟ್ಟು ವಿರಳನ ಸರಣಿಯನ್ನು ವರ್ಧಿಸಿ, ಪ್ರತಿಯೊಂದರ ಮಿತಿ ಚಕ್ರ ದಾಖಲಿಸಿ, ದಕ್ಷತೆ ಮತ್ತು ಅಜ್ಞಾತದಲ್ಲಿನ ಪ್ರತಿಗಳನ್ನು ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To make a qPCR standard curve, find the amplification efficiency and quantify an unknown sample.', 'qPCR मानक वक्र बनाना, प्रवर्धन दक्षता ज्ञात करना और एक अज्ञात नमूने का परिमाण निकालना।', 'qPCR ಪ್ರಮಾಣಿತ ವಕ್ರ ರಚಿಸಿ, ವರ್ಧನ ದಕ್ಷತೆ ಕಂಡುಹಿಡಿದು ಅಜ್ಞಾತ ಮಾದರಿಯ ಪ್ರಮಾಣ ಅಳೆಯುವುದು.'),
        principle=W('Each cycle (denature at 95 °C, anneal primers at 55 °C, extend at 72 °C) multiplies the target by (1 + E), where E = 1 for perfect doubling, until reagents run short. The cycle at which fluorescence crosses a threshold, Ct, falls by log₂10 ≈ 3.32 for every ten-fold increase in starting copies. A plot of Ct against log₁₀N₀ is a straight line; E = 10^(−1/slope) − 1.', 'हर चक्र (95 °C पर विकृतीकरण, 55 °C पर प्राइमर संलयन, 72 °C पर विस्तार) लक्ष्य को (1 + E) से गुणा करता है, जहाँ पूर्ण द्विगुणन के लिए E = 1, जब तक अभिकर्मक कम न पड़ें। प्रतिदीप्ति जिस चक्र पर थ्रेशोल्ड पार करती है, Ct, प्रारंभिक प्रतियों में हर दस गुना वृद्धि पर log₂10 ≈ 3.32 घटता है। log₁₀N₀ के विरुद्ध Ct का आलेख सीधी रेखा है; E = 10^(−1/ढाल) − 1।', 'ಪ್ರತಿ ಚಕ್ರ (95 °C ನಲ್ಲಿ ವಿಕೃತಿ, 55 °C ನಲ್ಲಿ ಪ್ರೈಮರ್ ಜೋಡಣೆ, 72 °C ನಲ್ಲಿ ವಿಸ್ತರಣೆ) ಗುರಿಯನ್ನು (1 + E) ಯಿಂದ ಗುಣಿಸುತ್ತದೆ; ಪರಿಪೂರ್ಣ ದ್ವಿಗುಣಕ್ಕೆ E = 1, ಕಾರಕಗಳು ಕೊರತೆಯಾಗುವವರೆಗೆ. ಪ್ರತಿದೀಪ್ತಿ ಮಿತಿಯನ್ನು ದಾಟುವ ಚಕ್ರ Ct, ಆರಂಭಿಕ ಪ್ರತಿಗಳು ಹತ್ತು ಪಟ್ಟು ಹೆಚ್ಚಿದಾಗ log₂10 ≈ 3.32 ಇಳಿಯುತ್ತದೆ. log₁₀N₀ ವಿರುದ್ಧ Ct ನಕ್ಷೆ ನೇರ ರೇಖೆ; E = 10^(−1/ಇಳಿಜಾರು) − 1.'),
        apparatus=[W('Real-time thermocycler', 'रियल-टाइम थर्मोसाइक्लर', 'ರಿಯಲ್-ಟೈಮ್ ಥರ್ಮೋಸೈಕ್ಲರ್'), W('Template dilutions (10³–10⁷ copies), primers and master mix with dye', 'टेम्पलेट तनुकरण (10³–10⁷ प्रतियाँ), प्राइमर और डाई सहित मास्टर मिक्स', 'ಟೆಂಪ್ಲೇಟ್ ವಿರಳನಗಳು (10³–10⁷ ಪ್ರತಿಗಳು), ಪ್ರೈಮರ್‌ಗಳು ಮತ್ತು ಬಣ್ಣ ಸಹಿತ ಮಾಸ್ಟರ್ ಮಿಕ್ಸ್'), W('Micropipettes with filter tips and PCR tubes', 'फ़िल्टर टिप सहित माइक्रोपिपेट और PCR नलियाँ', 'ಫಿಲ್ಟರ್ ತುದಿಗಳ ಮೈಕ್ರೋಪಿಪೆಟ್‌ಗಳು ಮತ್ತು PCR ನಳಿಕೆಗಳು')],
        steps=[W('Set up reactions for each standard and the unknown, with a no-template control.', 'हर मानक और अज्ञात के लिए अभिक्रियाएँ तैयार करें, एक बिना-टेम्पलेट नियंत्रण के साथ।', 'ಪ್ರತಿ ಪ್ರಮಾಣಿತ ಮತ್ತು ಅಜ್ಞಾತಕ್ಕೆ ಪ್ರತಿಕ್ರಿಯೆಗಳನ್ನು ಸಿದ್ಧಪಡಿಸಿ, ಟೆಂಪ್ಲೇಟ್ ಇಲ್ಲದ ನಿಯಂತ್ರಣದೊಂದಿಗೆ.'),
               W('Run 40 cycles, watching the fluorescence rise.', '40 चक्र चलाएँ, प्रतिदीप्ति बढ़ते देखें।', '40 ಚಕ್ರಗಳನ್ನು ಓಡಿಸಿ, ಪ್ರತಿದೀಪ್ತಿ ಏರುವುದನ್ನು ಗಮನಿಸಿ.'),
               W('Record the Ct of each sample where its curve crosses the threshold.', 'हर नमूने का Ct दर्ज करें जहाँ उसका वक्र थ्रेशोल्ड पार करता है।', 'ಪ್ರತಿ ಮಾದರಿಯ ವಕ್ರ ಮಿತಿಯನ್ನು ದಾಟುವಲ್ಲಿ ಅದರ Ct ದಾಖಲಿಸಿ.'),
               W('Fit Ct against log₁₀N₀, find the efficiency, and read the unknown off the line.', 'log₁₀N₀ के विरुद्ध Ct फ़िट करें, दक्षता ज्ञात करें, और रेखा से अज्ञात पढ़ें।', 'log₁₀N₀ ವಿರುದ್ಧ Ct ಹೊಂದಿಸಿ, ದಕ್ಷತೆ ಕಂಡುಹಿಡಿದು ರೇಖೆಯಿಂದ ಅಜ್ಞಾತ ಓದಿ.')],
        precautions=[W('Keep pre- and post-PCR work apart and use filter tips to avoid contamination.', 'संदूषण से बचने के लिए PCR से पहले और बाद का काम अलग रखें और फ़िल्टर टिप लें।', 'ಮಾಲಿನ್ಯ ತಪ್ಪಿಸಲು PCR ಮೊದಲು ಮತ್ತು ನಂತರದ ಕೆಲಸವನ್ನು ಬೇರೆಯಾಗಿಡಿ, ಫಿಲ್ಟರ್ ತುದಿಗಳನ್ನು ಬಳಸಿ.'), W('Run each standard at least in duplicate.', 'हर मानक कम से कम दो बार चलाएँ।', 'ಪ್ರತಿ ಪ್ರಮಾಣಿತವನ್ನು ಕನಿಷ್ಠ ಎರಡು ಬಾರಿ ಓಡಿಸಿ.')],
        conclusion=W('Ct falls by about 3.4 cycles per ten-fold increase in template, an efficiency near 95 %; the unknown holds about 4 × 10⁴ copies.', 'टेम्पलेट में हर दस गुना वृद्धि पर Ct लगभग 3.4 चक्र घटता है, दक्षता लगभग 95 %; अज्ञात में लगभग 4 × 10⁴ प्रतियाँ हैं।', 'ಟೆಂಪ್ಲೇಟ್ ಹತ್ತು ಪಟ್ಟು ಹೆಚ್ಚಿದಾಗ Ct ಸುಮಾರು 3.4 ಚಕ್ರ ಇಳಿಯುತ್ತದೆ, ದಕ್ಷತೆ ಸುಮಾರು 95 %; ಅಜ್ಞಾತದಲ್ಲಿ ಸುಮಾರು 4 × 10⁴ ಪ್ರತಿಗಳಿವೆ.'),
        viva=[Q(W('Which enzyme is used in PCR and why?', 'PCR में कौन-सा एंज़ाइम प्रयुक्त होता है और क्यों?', 'PCR ನಲ್ಲಿ ಯಾವ ಕಿಣ್ವ ಬಳಸುತ್ತಾರೆ, ಏಕೆ?'), W('Taq polymerase, from a hot-spring bacterium: it survives 95 °C.', 'टैक पॉलिमरेज़, गर्म झरने के जीवाणु से: यह 95 °C सह लेता है।', 'ಟ್ಯಾಕ್ ಪಾಲಿಮರೇಸ್, ಬಿಸಿನೀರ ಬುಗ್ಗೆಯ ಬ್ಯಾಕ್ಟೀರಿಯಾದಿಂದ: ಅದು 95 °C ತಾಳುತ್ತದೆ.')),
              Q(W('Why does the curve level off?', 'वक्र स्थिर क्यों हो जाता है?', 'ವಕ್ರ ಏಕೆ ಸಮತಟ್ಟಾಗುತ್ತದೆ?'), W('Primers and nucleotides run short and the enzyme tires (plateau).', 'प्राइमर और न्यूक्लियोटाइड कम पड़ जाते हैं और एंज़ाइम थक जाता है (पठार)।', 'ಪ್ರೈಮರ್ ಮತ್ತು ನ್ಯೂಕ್ಲಿಯೋಟೈಡ್‌ಗಳು ಕೊರತೆಯಾಗುತ್ತವೆ, ಕಿಣ್ವ ದಣಿಯುತ್ತದೆ (ಪ್ರಸ್ಥಭೂಮಿ).')),
              Q(W('What slope means 100 % efficiency?', 'कौन-सी ढाल 100 % दक्षता दर्शाती है?', 'ಯಾವ ಇಳಿಜಾರು 100 % ದಕ್ಷತೆ ಸೂಚಿಸುತ್ತದೆ?'), W('−3.32 cycles per ten-fold dilution.', 'हर दस गुना तनुकरण पर −3.32 चक्र।', 'ಪ್ರತಿ ಹತ್ತು ಪಟ್ಟು ವಿರಳನಕ್ಕೆ −3.32 ಚಕ್ರ.'))])
